import {
  assign,
  enqueueActions,
  sendTo,
  setup,
  type SnapshotEvent,
} from "xstate";
import {
  bridgeCommand,
  dismissStepCommand,
  revealStepCommand,
  zoneRevealBeforeToken,
} from "../domain/commandBuilders";
import type {
  LearningPathEvent,
  LearningPathMachineContext,
  LearningPathMachineInput,
  NavigationRejectedNotice,
  OrchestrationServices,
  PresentationCommand,
  RecoveryFailureKind,
  RecoveryRequest,
} from "../domain/orchestrationTypes";
import { createRecoveredLearningPathContext } from "./context";
import {
  createRecoveryMachine,
  selectRecoveryCommand,
  type RecoveryMachineOutput,
  type RecoveryMachineSnapshot,
} from "../../workflows/recovery";
import {
  createNavigationIntent,
  createNavigationMachine,
  projectNavigation,
  type NavigationCommand,
  type NavigationEvent,
  type NavigationFailure,
  type NavigationMachineSnapshot,
  type NavigationPhase,
} from "../../workflows/navigation";
import {
  createZoneSessionMachine,
  projectZoneSession,
  type ZoneSessionSnapshot,
  type ZoneSessionStateValue,
} from "../../workflows/zone-session";

function recoverySnapshotFromEvent(event: unknown): RecoveryMachineSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<RecoveryMachineSnapshot>).snapshot;
}

function recoveryOutputFromEvent(event: unknown): RecoveryMachineOutput | null {
  if (typeof event !== "object" || event === null || !("output" in event)) return null;
  return (event as { readonly output?: RecoveryMachineOutput }).output ?? null;
}

function navigationSnapshotFromEvent(event: unknown): NavigationMachineSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<NavigationMachineSnapshot>).snapshot;
}

function zoneSessionSnapshotFromEvent(event: unknown): ZoneSessionSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<ZoneSessionSnapshot>).snapshot;
}

function navigationEpoch(context: LearningPathMachineContext): string {
  return `${context.navigationEpochBase}:epoch:${context.navigationEpochRevision}`;
}

function navigationCommandCorrelationMatches(
  expected: NavigationCommand | null,
  event: LearningPathEvent,
): boolean {
  if (expected === null
    || !("token" in event)
    || !("transactionId" in event)
    || !("operationId" in event)
    || !("attemptId" in event)
    || !("attempt" in event)) {
    return false;
  }
  const expectedToken = expected.type === "CHARACTER.FORCE_SETTLE"
    ? expected.attemptId
    : expected.token;
  return event.token === expectedToken
    && event.transactionId === expected.transactionId
    && event.operationId === expected.operationId
    && event.attemptId === expected.attemptId
    && event.attempt === expected.attempt;
}

type NavigationGatewayEvent = Extract<
  LearningPathEvent,
  {
    readonly type:
      | "PRESENTATION.SETTLED"
      | "PRESENTATION.FAILED"
      | "PRESENTATION.TIMED_OUT"
      | "MOTION.DEPARTED"
      | "MOTION.ARRIVED"
      | "MOTION.VISUAL_IDLE"
      | "MOTION.FAILED"
      | "MOTION.TIMED_OUT"
      | "CHARACTER.SETTLED"
      | "CHARACTER.FAILED";
  }
>;

function isNavigationGatewayEvent(
  event: LearningPathEvent,
): event is NavigationGatewayEvent {
  return event.type === "PRESENTATION.SETTLED"
    || event.type === "PRESENTATION.FAILED"
    || event.type === "PRESENTATION.TIMED_OUT"
    || event.type === "MOTION.DEPARTED"
    || event.type === "MOTION.ARRIVED"
    || event.type === "MOTION.VISUAL_IDLE"
    || event.type === "MOTION.FAILED"
    || event.type === "MOTION.TIMED_OUT"
    || event.type === "CHARACTER.SETTLED"
    || event.type === "CHARACTER.FAILED";
}

function zoneCommandCandidates(
  context: LearningPathMachineContext,
): readonly PresentationCommand[] {
  const candidates: PresentationCommand[] = [];
  const revealPlan = context.zoneRevealPlan;
  if (revealPlan) {
    const beforeAction = revealPlan.beforeRevealBridgeActions[
      context.zoneRevealBeforeActionIndex
    ];
    if (beforeAction) {
      const operationId = zoneRevealBeforeToken(
        revealPlan.id,
        context.zoneRevealBeforeActionIndex,
      );
      candidates.push(bridgeCommand(
        operationId,
        context.zoneRevealCommandAttempt,
        "zone-reveal-before",
        revealPlan.id,
        context.zoneRevealBeforeActionIndex,
        beforeAction,
      ));
    }
    if (revealPlan.steps[context.zoneRevealStepIndex]) {
      candidates.push(revealStepCommand(
        revealPlan,
        context.zoneRevealStepIndex,
        context.zoneRevealCommandAttempt,
      ));
    }
  }
  const dismissPlan = context.zoneDismissPlan;
  if (dismissPlan?.steps[context.zoneDismissStepIndex]) {
    candidates.push(dismissStepCommand(
      dismissPlan,
      context.zoneDismissStepIndex,
      context.zoneDismissCommandAttempt,
      dismissPlan.linkedNavigationPlanId
        ? context.navigationLinkedCleanupCorrelation?.transactionId
        : null,
    ));
  }
  return candidates;
}

function zonePresentationCorrelationMatches(
  context: LearningPathMachineContext,
  event: LearningPathEvent,
): boolean {
  if ((event.type !== "PRESENTATION.SETTLED"
      && event.type !== "PRESENTATION.FAILED"
      && event.type !== "PRESENTATION.TIMED_OUT")) {
    return false;
  }
  return zoneCommandCandidates(context).some((expected) => (
    event.token === expected.token
    && event.transactionId === expected.transactionId
    && event.operationId === expected.operationId
    && event.attemptId === expected.attemptId
    && event.attempt === expected.attempt
  ));
}

function toNavigationGatewayEvent(
  context: LearningPathMachineContext,
  event: LearningPathEvent,
): NavigationEvent {
  const command = context.navigationWorkflowCommand;
  if (!command
    || !isNavigationGatewayEvent(event)
    || !navigationCommandCorrelationMatches(command, event)) {
    throw new Error("Cannot forward an uncorrelated navigation gateway event.");
  }
  const correlation = {
    epoch: command.epoch,
    sequence: command.sequence,
    transactionId: event.transactionId,
    operationId: event.operationId,
    attemptId: event.attemptId,
    attempt: event.attempt,
    token: event.token,
  };
  switch (event.type) {
    case "PRESENTATION.SETTLED":
      return { type: event.type, ...correlation };
    case "PRESENTATION.FAILED":
    case "PRESENTATION.TIMED_OUT":
      return { type: event.type, ...correlation, error: event.error };
    case "MOTION.DEPARTED":
      return { type: event.type, ...correlation, fromNodeId: event.fromNodeId };
    case "MOTION.ARRIVED":
    case "MOTION.VISUAL_IDLE":
      return { type: event.type, ...correlation, nodeId: event.nodeId };
    case "MOTION.FAILED":
    case "MOTION.TIMED_OUT":
      return { type: event.type, ...correlation, error: event.error };
    case "CHARACTER.SETTLED":
      return { type: event.type, ...correlation };
    case "CHARACTER.FAILED":
      return {
        type: event.type,
        ...correlation,
        error: event.error,
        timedOut: event.timedOut,
      };
  }
}

function recoveryRequestFromNavigationFailure(
  failure: NavigationFailure,
): RecoveryRequest {
  return Object.freeze({
    recoveryId: `recovery:${failure.transactionId}:${failure.operationId}`,
    transactionId: failure.transactionId,
    operationId: failure.operationId,
    failedAttemptId: failure.attemptId,
    kind: failure.kind,
    error: failure.error,
    safeNodeId: failure.safeNodeId,
  });
}

function recoveryRequestFromZoneFailure(
  context: LearningPathMachineContext,
  event: Extract<
    LearningPathEvent,
    { readonly type: "ORCHESTRATION.ZONE.RECOVERY.REQUESTED" }
  >,
): RecoveryRequest {
  const failure = event.failure;
  const kind: RecoveryFailureKind = failure.type === "PRESENTATION.TIMED_OUT"
    ? "presentation-timeout"
    : "presentation-failed";
  return Object.freeze({
    recoveryId: `recovery:${failure.transactionId}:${failure.operationId}`,
    transactionId: failure.transactionId,
    operationId: failure.operationId,
    failedAttemptId: failure.token,
    kind,
    error: failure.error,
    safeNodeId: context.currentNodeId,
  });
}

/**
 * Wires focused child actors into the orchestration shell. Navigation and Zone
 * own business transitions and commands; the parent only routes, correlates,
 * projects compatibility fields, and escalates terminal failure to Recovery.
 */
export function createLearningPathOrchestrationSetup(
  services: OrchestrationServices,
) {
  return setup({
    types: {} as {
      context: LearningPathMachineContext;
      events: LearningPathEvent;
      input: LearningPathMachineInput;
    },
    actors: {
      navigationWorkflow: createNavigationMachine({
        planNavigation: services.planNavigation,
        commitNavigationBeforeAction: services.commitNavigationBeforeAction,
        commitNavigationStageStarted: services.commitNavigationStageStarted,
        commitNavigationAfterAction: services.commitNavigationAfterAction,
        commitNavigationStageArrived: services.commitNavigationStageArrived,
        executePresentation: services.executePresentation,
        executeMotion: services.executeMotion,
        executeCharacterForceSettle: services.executeCharacterForceSettle,
        onOperationRetry: services.onOperationRetry,
        onTransactionSettled: services.onNavigationTransactionSettled,
        characterNaturalSettleTimeoutMs: services.characterNaturalSettleTimeoutMs,
        characterForceSettleAckTimeoutMs: services.characterForceSettleAckTimeoutMs,
      }),
      recoveryWorkflow: createRecoveryMachine({
        commandTimeoutMs: services.recoveryCommandTimeoutMs,
        characterIdleTimeoutMs: services.recoveryCharacterIdleTimeoutMs,
      }),
      zoneSessionWorkflow: createZoneSessionMachine({
        planReveal: services.planZoneReveal,
        planDismiss: services.planZoneDismiss,
        commitRevealBeforeAction: services.commitZoneRevealBeforeAction,
        commitRevealStep: services.commitZoneRevealStep,
        commitDismissStep: services.commitZoneDismissStep,
        executePresentation: services.executePresentation,
        onOperationRetry: services.onOperationRetry,
        onStandaloneTransactionSettled: services.onStandaloneZoneTransactionSettled,
      }),
    },
    guards: {
      recoveryCompleteMatches: ({ context, event }) => (
        event.type === "ORCHESTRATION.RECOVERY.COMPLETE"
        && event.recoveryId === context.recoveryRequest?.recoveryId
        && event.transactionId === context.recoveryRequest.transactionId
      ),
      recoveryFailedMatches: ({ context, event }) => (
        event.type === "ORCHESTRATION.RECOVERY.FAILED"
        && event.recoveryId === context.recoveryRequest?.recoveryId
        && event.transactionId === context.recoveryRequest.transactionId
      ),
      canRequestZoneWork: ({ context }) => (
        context.navigationWorkflowPhase === "idle"
        && context.characterVisualIdle
      ),
      zonePresentationEventRelevant: ({ context, event }) => (
        zonePresentationCorrelationMatches(context, event)
      ),
      linkedDismissDepartureMatches: ({ context, event }) => (
        event.type === "MOTION.DEPARTED"
        && navigationCommandCorrelationMatches(
          context.navigationWorkflowCommand,
          event,
        )
        && context.zoneDismissPlan?.linkedNavigationPlanId
          === context.navigationPlan?.id
      ),
      zoneInitiallyActive: ({ context }) => context.zoneInitiallyActive,
      zonePhaseMatches: ({ event }, params: { readonly phase: ZoneSessionStateValue }) => (
        event.type === "ORCHESTRATION.ZONE.PHASE_CHANGED"
        && event.phase === params.phase
      ),
      navigationPhaseMatches: ({ event }, params: { readonly phase: NavigationPhase }) => (
        event.type === "ORCHESTRATION.NAVIGATION.PHASE_CHANGED"
        && event.phase === params.phase
      ),
      canFlushPendingNavigation: ({ context }) => (
        context.pendingNavigationTargetNodeId !== null
        && context.navigationWorkflowPhase === "idle"
        && !context.zoneTransitionActive
        && context.characterVisualIdle
      ),
      navigationPresentationEventRelevant: ({ context, event }) => (
        (event.type === "PRESENTATION.SETTLED"
          || event.type === "PRESENTATION.FAILED"
          || event.type === "PRESENTATION.TIMED_OUT")
        && context.navigationWorkflowCommand?.type === "PRESENTATION.BRIDGE"
        && navigationCommandCorrelationMatches(
          context.navigationWorkflowCommand,
          event,
        )
      ),
      navigationMotionEventRelevant: ({ context, event }) => (
        (event.type === "MOTION.DEPARTED"
          || event.type === "MOTION.ARRIVED"
          || event.type === "MOTION.VISUAL_IDLE"
          || event.type === "MOTION.FAILED"
          || event.type === "MOTION.TIMED_OUT")
        && context.navigationWorkflowCommand?.type === "MOTION.NAVIGATE"
        && navigationCommandCorrelationMatches(
          context.navigationWorkflowCommand,
          event,
        )
        && (event.type !== "MOTION.DEPARTED"
          || event.fromNodeId === context.navigationWorkflowCommand.fromNodeId)
        && (event.type !== "MOTION.ARRIVED"
          || event.nodeId === context.navigationWorkflowCommand.toNodeId)
        && (event.type !== "MOTION.VISUAL_IDLE"
          || event.nodeId === context.arrivedNodeId)
      ),
      navigationCharacterEventRelevant: ({ context, event }) => (
        (event.type === "CHARACTER.SETTLED" || event.type === "CHARACTER.FAILED")
        && context.navigationWorkflowCommand?.type === "CHARACTER.FORCE_SETTLE"
        && navigationCommandCorrelationMatches(
          context.navigationWorkflowCommand,
          event,
        )
      ),
      characterReadinessCanSync: ({ context }) => (
        context.navigationWorkflowPhase === "idle"
      ),
    },
    actions: {
      routeOrQueueNavigationIntent: enqueueActions(({ context, event, enqueue }) => {
        if (event.type !== "NAVIGATION.REQUESTED") return;
        if (context.navigationWorkflowPhase === "idle"
          && (context.zoneTransitionActive || !context.characterVisualIdle)) {
          enqueue.assign({
            pendingNavigationTargetNodeId: event.targetNodeId,
            queuedTargetNodeId: event.targetNodeId,
          });
          return;
        }
        const sequence = context.navigationSequence + 1;
        const epoch = navigationEpoch(context);
        const transactionId = `${epoch}:navigation:${sequence}`;
        const intent = createNavigationIntent(
          epoch,
          sequence,
          transactionId,
          event.targetNodeId,
        );
        enqueue.assign({
          navigationSequence: sequence,
          pendingNavigationTargetNodeId: null,
          requestedTargetNodeId: event.targetNodeId,
          queuedTargetNodeId: null,
        });
        enqueue.sendTo("navigationWorkflow", {
          type: "NAVIGATION.REQUESTED",
          ...intent,
        });
      }),
      queueLatestNavigationIntent: assign(({ event }) => {
        if (event.type !== "NAVIGATION.REQUESTED") return {};
        return {
          pendingNavigationTargetNodeId: event.targetNodeId,
          queuedTargetNodeId: event.targetNodeId,
        };
      }),
      flushPendingNavigationIntent: enqueueActions(({ context, enqueue }) => {
        const targetNodeId = context.pendingNavigationTargetNodeId;
        if (!targetNodeId) return;
        const sequence = context.navigationSequence + 1;
        const epoch = navigationEpoch(context);
        const transactionId = `${epoch}:navigation:${sequence}`;
        const intent = createNavigationIntent(
          epoch,
          sequence,
          transactionId,
          targetNodeId,
        );
        enqueue.assign({
          navigationSequence: sequence,
          pendingNavigationTargetNodeId: null,
          requestedTargetNodeId: targetNodeId,
          queuedTargetNodeId: null,
        });
        enqueue.sendTo("navigationWorkflow", {
          type: "NAVIGATION.REQUESTED",
          ...intent,
        });
      }),
      forwardNavigationGatewayEvent: sendTo(
        "navigationWorkflow",
        ({ context, event }) => toNavigationGatewayEvent(context, event),
      ),
      syncNavigationSnapshot: enqueueActions(({ context, event, enqueue }) => {
        const snapshot = navigationSnapshotFromEvent(event);
        if (!snapshot) return;
        const child = snapshot.context;
        const projection = projectNavigation(snapshot);
        const presentation = child.presentationCommand;
        const motion = child.motionCommand;
        const nextMotionToken = motion?.token ?? null;
        enqueue.assign({
          navigationWorkflowPhase: projection.phase,
          navigationWorkflowCommand: projection.command,
          navigationSequence: Math.max(
            context.navigationSequence,
            projection.latestSequence,
          ),
          currentNodeId: projection.currentNodeId,
          requestedTargetNodeId: projection.activeTargetNodeId,
          queuedTargetNodeId: projection.queuedTargetNodeId
            ?? context.pendingNavigationTargetNodeId,
          navigationPlan: child.plan,
          navigationStageIndex: child.stageIndex,
          navigationBeforeActionIndex: child.beforeActionIndex,
          navigationAfterActionIndex: child.afterActionIndex,
          navigationCommandToken: presentation?.token ?? null,
          navigationCommandAttempt: presentation?.attempt ?? 1,
          motionCommandToken: nextMotionToken,
          navigationStageStartedCommitted: child.stageStartedCommitted,
          arrivedNodeId: child.arrivedNodeId,
          linkedZoneCleanupComplete: child.linkedCleanupComplete,
          characterVisualIdle: child.characterVisualIdle,
        });
        if (nextMotionToken && nextMotionToken !== context.motionCommandToken) {
          enqueue.raise({
            type: "ORCHESTRATION.MOTION.ISSUED",
            token: nextMotionToken,
          });
        }
      }),
      raiseNavigationProjection: enqueueActions(({ event, enqueue }) => {
        const snapshot = navigationSnapshotFromEvent(event);
        if (!snapshot) return;
        enqueue.raise({
          type: "ORCHESTRATION.NAVIGATION.PHASE_CHANGED",
          phase: projectNavigation(snapshot).phase,
        });
      }),
      armLinkedZoneCleanup: enqueueActions(({ event, enqueue }) => {
        if (event.type !== "NAVIGATION.LINKED_ZONE_CLEANUP.REQUESTED") return;
        enqueue.assign({
          navigationLinkedCleanupCorrelation: event.completion,
          navigationLinkedCleanupPlanId: event.navigationPlanId,
        });
        enqueue.sendTo("zoneSessionWorkflow", {
          type: "ZONE.LINKED_DISMISS.ARMED",
          plan: event.plan,
          navigationPlanId: event.navigationPlanId,
          navigationTransactionId: event.transactionId,
          motionToken: event.motionToken,
        });
        // The navigation actor must not publish the synchronous departure event
        // until the zone actor has received this linked-dismiss envelope.
        enqueue.sendTo("navigationWorkflow", {
          type: "ZONE.CLEANUP.ARMED",
          navigationPlanId: event.navigationPlanId,
          token: event.motionToken,
          epoch: event.epoch,
          sequence: event.sequence,
          transactionId: event.transactionId,
          operationId: event.operationId,
          attemptId: event.attemptId,
          attempt: event.attempt,
        });
      }),
      forwardLinkedCleanupComplete: enqueueActions(({ context, event, enqueue }) => {
        if (event.type !== "ORCHESTRATION.CLEANUP.COMPLETE"
          || event.navigationPlanId !== context.navigationLinkedCleanupPlanId
          || context.navigationLinkedCleanupCorrelation === null) {
          return;
        }
        const correlation = context.navigationLinkedCleanupCorrelation;
        enqueue.sendTo("navigationWorkflow", {
          type: "ZONE.CLEANUP.COMPLETED",
          navigationPlanId: event.navigationPlanId,
          ...correlation,
        });
        enqueue.assign({
          navigationLinkedCleanupCorrelation: null,
          navigationLinkedCleanupPlanId: null,
        });
      }),
      notifyNavigationSettled: enqueueActions(({ event, enqueue }) => {
        if (event.type !== "NAVIGATION.SETTLED") return;
        enqueue(() => services.onNavigationSettled?.(Object.freeze({
          transactionId: event.transactionId,
          planId: event.planId,
          nodeId: event.nodeId,
        })));
        enqueue.assign({
          navigationLinkedCleanupCorrelation: null,
          navigationLinkedCleanupPlanId: null,
        });
      }),
      notifyNavigationRejected: enqueueActions(({ event, enqueue }) => {
        if (event.type !== "NAVIGATION.REJECTED") return;
        const notice: NavigationRejectedNotice = Object.freeze({
          sourceNodeId: event.sourceNodeId,
          targetNodeId: event.targetNodeId,
          reason: event.reason,
          detail: event.detail,
        });
        enqueue(() => services.onNavigationRejected?.(notice));
        enqueue.assign({
          lastRejectedNavigation: notice,
          requestedTargetNodeId: null,
        });
      }),
      syncCharacterVisualIdle: assign(({ event }) => {
        if (event.type !== "ORCHESTRATION.CHARACTER.VISUAL_IDLE_CHANGED") {
          return {};
        }
        return { characterVisualIdle: event.visuallyIdle };
      }),
      recordCharacterFailure: assign(({ event }) => {
        if (event.type !== "ORCHESTRATION.CHARACTER.FAILED") return {};
        return {
          characterVisualIdle: false,
          requestedTargetNodeId: null,
          pendingNavigationTargetNodeId: null,
          queuedTargetNodeId: null,
          fatalError: event.error,
        };
      }),
      forwardZoneRequest: sendTo("zoneSessionWorkflow", ({ context, event }) => {
        if (event.type === "ZONE.REVEAL.REQUESTED") {
          return {
            type: event.type,
            nodeId: event.nodeId ?? context.currentNodeId,
          };
        }
        if (event.type === "ZONE.DISMISS.REQUESTED") {
          return {
            type: event.type,
            nodeId: event.nodeId ?? context.currentNodeId,
          };
        }
        throw new Error(`Cannot forward zone request ${event.type}.`);
      }),
      forwardZonePresentationEvent: sendTo(
        "zoneSessionWorkflow",
        ({ event }) => {
          if (event.type === "PRESENTATION.SETTLED") {
            return { type: event.type, token: event.token };
          }
          if (event.type === "PRESENTATION.FAILED"
            || event.type === "PRESENTATION.TIMED_OUT") {
            return {
              type: event.type,
              token: event.token,
              operationId: event.operationId,
              transactionId: event.transactionId,
              error: event.error,
            };
          }
          throw new Error(`Cannot forward zone presentation event ${event.type}.`);
        },
      ),
      forwardZoneDeparture: sendTo(
        "zoneSessionWorkflow",
        ({ event }) => {
          if (event.type !== "MOTION.DEPARTED") {
            throw new Error(`Cannot forward zone departure ${event.type}.`);
          }
          return {
            type: event.type,
            token: event.token,
            fromNodeId: event.fromNodeId,
          };
        },
      ),
      syncZoneSessionSnapshot: assign(({ event }) => {
        const snapshot = zoneSessionSnapshotFromEvent(event);
        if (!snapshot) return {};
        const projection = projectZoneSession(snapshot);
        return {
          zoneRevealPlan: projection.revealPlan,
          zoneRevealBeforeActionIndex: projection.revealBeforeActionIndex,
          zoneRevealStepIndex: projection.revealStepIndex,
          zoneRevealCommandToken: projection.revealCommandToken,
          zoneRevealCommandAttempt: projection.revealCommandAttempt,
          zoneDismissPlan: projection.dismissPlan,
          zoneDismissStepIndex: projection.dismissStepIndex,
          zoneDismissCommandToken: projection.dismissCommandToken,
          zoneDismissCommandAttempt: projection.dismissCommandAttempt,
          zoneTransitionActive: projection.transitionActive,
        };
      }),
      raiseZoneSessionProjection: enqueueActions(({ event, enqueue }) => {
        const snapshot = zoneSessionSnapshotFromEvent(event);
        if (!snapshot) return;
        enqueue.raise({
          type: "ORCHESTRATION.ZONE.PHASE_CHANGED",
          phase: projectZoneSession(snapshot).phase,
        });
      }),
      recordNavigationRecoveryRequest: assign(({ event }) => {
        if (event.type !== "NAVIGATION.RECOVERY.REQUESTED") return {};
        return {
          recoveryRequest: recoveryRequestFromNavigationFailure(event),
          requestedTargetNodeId: null,
          navigationCommandToken: null,
          motionCommandToken: null,
          zoneRevealCommandToken: null,
          zoneDismissCommandToken: null,
          characterVisualIdle: false,
        };
      }),
      recordZoneRecoveryRequest: assign(({ context, event }) => {
        if (event.type !== "ORCHESTRATION.ZONE.RECOVERY.REQUESTED") return {};
        return {
          recoveryRequest: recoveryRequestFromZoneFailure(context, event),
          requestedTargetNodeId: null,
          navigationCommandToken: null,
          motionCommandToken: null,
          zoneRevealCommandToken: null,
          zoneDismissCommandToken: null,
          characterVisualIdle: false,
        };
      }),
      notifyRecoveryStarted: ({ context }) => {
        if (context.recoveryRequest) services.onRecoveryStarted?.(context.recoveryRequest);
      },
      dispatchRecoveryCommand: ({ event }) => {
        const snapshot = recoverySnapshotFromEvent(event);
        const command = snapshot ? selectRecoveryCommand(snapshot) : null;
        if (command) services.executeRecoveryCommand(command);
      },
      finalizeRecoveryWorkflow: ({ context, event }) => {
        const output = recoveryOutputFromEvent(event);
        if (context.recoveryRequest && output) {
          services.finalizeRecovery(context.recoveryRequest, output);
        }
      },
      cleanupRecoveryAdapter: ({ context }) => {
        if (context.recoveryRequest) services.cancelRecovery(context.recoveryRequest);
      },
      recordRecoveryActorFailure: assign(({ event }) => ({
        fatalError: typeof event === "object" && event !== null && "error" in event
          ? `Recovery actor failed: ${String(event.error)}`
          : "Recovery actor failed without an error payload.",
        characterVisualIdle: false,
      })),
      completeRecovery: assign(({ context, event }) => {
        if (event.type !== "ORCHESTRATION.RECOVERY.COMPLETE") return {};
        return createRecoveredLearningPathContext(context, event);
      }),
      recordRecoveryFailure: assign(({ event }) => {
        if (event.type !== "ORCHESTRATION.RECOVERY.FAILED") return {};
        return { fatalError: event.error, characterVisualIdle: false };
      }),
      forwardRecoveryAck: sendTo("recoveryWorkflow", ({ event }) => event),
    },
  });
}
