import type { NodeId } from "../../config/pathData";
import type { NavigationPlan } from "../../simulation/PathRuleCoordinator";
import type {
  NavigationCharacterSettleCommand,
  NavigationCorrelation,
  NavigationIntent,
  NavigationMotionCommand,
  NavigationPresentationCommand,
} from "./types";

function nonEmpty(value: string, label: string): string {
  if (value.length === 0) throw new Error(`${label} must be non-empty.`);
  return value;
}

function safeOrdinal(value: number, label: string, allowZero = false): number {
  if (!Number.isSafeInteger(value) || value < (allowZero ? 0 : 1)) {
    throw new Error(`${label} must be a ${allowZero ? "non-negative" : "positive"} safe integer.`);
  }
  return value;
}

export function validateNavigationCorrelation(
  correlation: NavigationCorrelation,
  options: Readonly<{ allowSequenceZero?: boolean }> = {},
): NavigationCorrelation {
  nonEmpty(correlation.epoch, "epoch");
  safeOrdinal(correlation.sequence, "sequence", options.allowSequenceZero ?? false);
  nonEmpty(correlation.transactionId, "transactionId");
  nonEmpty(correlation.operationId, "operationId");
  nonEmpty(correlation.attemptId, "attemptId");
  safeOrdinal(correlation.attempt, "attempt");
  return correlation;
}

export function navigationAttemptId(operationId: string, attempt: number): string {
  return `${operationId}:attempt:${attempt}`;
}

export function createNavigationIntent(
  epoch: string,
  sequence: number,
  transactionId: string,
  targetNodeId: NodeId,
): NavigationIntent {
  const operationId = `${transactionId}:request`;
  return Object.freeze({
    epoch,
    sequence,
    transactionId,
    operationId,
    attemptId: navigationAttemptId(operationId, 1),
    attempt: 1,
    targetNodeId,
  });
}

export function navigationPresentationCommand(
  intent: NavigationIntent,
  plan: NavigationPlan,
  stageIndex: number,
  timing: "before" | "after",
  actionIndex: number,
  attempt: number,
): NavigationPresentationCommand {
  const stage = plan.stages[stageIndex];
  const action = timing === "before"
    ? stage?.beforeTravelBridgeActions[actionIndex]
    : stage?.afterArrivalBridgeActions[actionIndex];
  if (!stage || !action) {
    throw new Error(`Navigation plan "${plan.id}" has no ${timing} action ${actionIndex} at stage ${stageIndex}.`);
  }
  const operationId = `${intent.transactionId}:stage:${stageIndex}:${timing}:${actionIndex}`;
  const attemptId = navigationAttemptId(operationId, attempt);
  return Object.freeze({
    type: "PRESENTATION.BRIDGE",
    token: attemptId,
    epoch: intent.epoch,
    sequence: intent.sequence,
    transactionId: intent.transactionId,
    operationId,
    attemptId,
    attempt,
    lane: timing === "before" ? "navigation-before" : "navigation-after-arrival",
    planId: plan.id,
    stageIndex,
    stepIndex: actionIndex,
    action,
  });
}

export function navigationMotionCommand(
  intent: NavigationIntent,
  plan: NavigationPlan,
  stageIndex: number,
  attempt = 1,
): NavigationMotionCommand {
  const stage = plan.stages[stageIndex];
  if (!stage) {
    throw new Error(`Navigation plan "${plan.id}" has no stage ${stageIndex}.`);
  }
  const operationId = `${intent.transactionId}:stage:${stageIndex}:motion:${stage.id}`;
  const attemptId = navigationAttemptId(operationId, attempt);
  return Object.freeze({
    type: "MOTION.NAVIGATE",
    token: attemptId,
    epoch: intent.epoch,
    sequence: intent.sequence,
    transactionId: intent.transactionId,
    operationId,
    attemptId,
    attempt,
    navigationPlanId: plan.id,
    stageId: stage.id,
    stageIndex,
    fromNodeId: stage.fromNodeId,
    toNodeId: stage.toNodeId,
    routeNodeIds: Object.freeze([...stage.routeNodeIds]),
    routeEdgeIds: Object.freeze([...stage.routeEdgeIds]),
  });
}

export function linkedCleanupCorrelation(
  intent: NavigationIntent,
): NavigationCorrelation {
  const operationId = `${intent.transactionId}:linked-zone-cleanup`;
  return Object.freeze({
    epoch: intent.epoch,
    sequence: intent.sequence,
    transactionId: intent.transactionId,
    operationId,
    attemptId: navigationAttemptId(operationId, 1),
    attempt: 1,
  });
}

export function navigationSettleCorrelation(
  intent: NavigationIntent,
): NavigationCorrelation {
  const operationId = `${intent.transactionId}:settled`;
  return Object.freeze({
    epoch: intent.epoch,
    sequence: intent.sequence,
    transactionId: intent.transactionId,
    operationId,
    attemptId: navigationAttemptId(operationId, 1),
    attempt: 1,
  });
}

export function navigationCharacterSettleCommand(
  intent: NavigationIntent,
  motionCommand: NavigationMotionCommand,
  arrivedNodeId: NodeId,
  operationId: string,
  attemptId: string,
  attempt: number,
): NavigationCharacterSettleCommand {
  return Object.freeze({
    type: "CHARACTER.FORCE_SETTLE",
    motionToken: motionCommand.token,
    arrivedNodeId,
    reason: "motion-arrived-not-visually-idle",
    epoch: intent.epoch,
    sequence: intent.sequence,
    transactionId: intent.transactionId,
    operationId,
    attemptId,
    attempt,
  });
}

export function correlationMatches(
  expected: NavigationCorrelation | null,
  actual: NavigationCorrelation,
): boolean {
  return expected !== null
    && actual.epoch === expected.epoch
    && actual.sequence === expected.sequence
    && actual.transactionId === expected.transactionId
    && actual.operationId === expected.operationId
    && actual.attemptId === expected.attemptId
    && actual.attempt === expected.attempt;
}
