import { assign, setup, type SnapshotFrom } from "xstate";
import type {
  CharacterForceSettleCommand,
  CharacterSettleContext,
  CharacterSettleEvent,
  CharacterSettleFailure,
  CharacterSettleMachineInput,
  CharacterSettleMachineOptions,
  CharacterSettleMachineOutput,
} from "./types";

const DEFAULT_NATURAL_SETTLE_TIMEOUT_MS = 1_200;
const DEFAULT_FORCED_SETTLE_ACK_TIMEOUT_MS = 1_200;

function requireNonEmpty(value: string, label: string): string {
  if (value.length === 0) throw new Error(`${label} must be non-empty.`);
  return value;
}

export function createCharacterForceSettleCommand(
  input: CharacterSettleMachineInput,
): CharacterForceSettleCommand {
  const operationId = `${input.motionOperationId}:character-settle`;
  return Object.freeze({
    type: "CHARACTER.FORCE_SETTLE",
    motionToken: input.motionToken,
    arrivedNodeId: input.arrivedNodeId,
    transactionId: input.transactionId,
    operationId,
    attemptId: `${operationId}:attempt:1`,
    attempt: 1,
    reason: "motion-arrived-not-visually-idle",
  });
}

function createInitialContext(
  input: CharacterSettleMachineInput,
): CharacterSettleContext {
  if (!Number.isSafeInteger(input.motionAttempt) || input.motionAttempt < 1) {
    throw new Error("motionAttempt must be a positive safe integer.");
  }
  const normalized = Object.freeze({
    motionToken: requireNonEmpty(input.motionToken, "motionToken"),
    transactionId: requireNonEmpty(input.transactionId, "transactionId"),
    motionOperationId: requireNonEmpty(input.motionOperationId, "motionOperationId"),
    motionAttempt: input.motionAttempt,
    arrivedNodeId: requireNonEmpty(input.arrivedNodeId, "arrivedNodeId"),
  });
  return Object.freeze({
    ...normalized,
    command: createCharacterForceSettleCommand(normalized),
    settledBy: null,
    failure: null,
  });
}

function commandCorrelationMatches(
  context: CharacterSettleContext,
  event: CharacterSettleEvent,
): boolean {
  return (event.type === "CHARACTER.SETTLED" || event.type === "CHARACTER.FAILED")
    && event.transactionId === context.command.transactionId
    && event.operationId === context.command.operationId
    && event.attemptId === context.command.attemptId
    && event.attempt === context.command.attempt;
}

function visualIdleMatches(
  context: CharacterSettleContext,
  event: CharacterSettleEvent,
): boolean {
  return event.type === "MOTION.VISUAL_IDLE"
    && event.token === context.motionToken
    && event.nodeId === context.arrivedNodeId;
}

function timeoutFailure(context: CharacterSettleContext): CharacterSettleFailure {
  return Object.freeze({
    kind: "force-settle-timeout",
    error: "Character failed to reach a stable idle pose after forced settle.",
    command: context.command,
  });
}

/**
 * Owns the complete post-arrival settle deadline. It first allows the natural
 * run-stop animation to finish, emits one force-settle command, then waits for
 * a fully correlated ACK before either succeeding or failing.
 */
export function createCharacterSettleMachine(
  options: CharacterSettleMachineOptions = {},
) {
  const naturalSettleTimeoutMs = options.naturalSettleTimeoutMs
    ?? DEFAULT_NATURAL_SETTLE_TIMEOUT_MS;
  const forcedSettleAckTimeoutMs = options.forcedSettleAckTimeoutMs
    ?? DEFAULT_FORCED_SETTLE_ACK_TIMEOUT_MS;
  if (!Number.isFinite(naturalSettleTimeoutMs) || naturalSettleTimeoutMs < 0) {
    throw new Error("naturalSettleTimeoutMs must be a finite non-negative number.");
  }
  if (!Number.isFinite(forcedSettleAckTimeoutMs) || forcedSettleAckTimeoutMs < 0) {
    throw new Error("forcedSettleAckTimeoutMs must be a finite non-negative number.");
  }

  return setup({
    types: {} as {
      context: CharacterSettleContext;
      events: CharacterSettleEvent;
      input: CharacterSettleMachineInput;
      output: CharacterSettleMachineOutput;
    },
    delays: {
      naturalSettleTimeout: naturalSettleTimeoutMs,
      forcedSettleAckTimeout: forcedSettleAckTimeoutMs,
    },
    guards: {
      visualIdleMatches: ({ context, event }) => visualIdleMatches(context, event),
      dispatchMatches: ({ context, event }) => (
        event.type === "CHARACTER.SETTLE.COMMAND_DISPATCHED"
        && event.attemptId === context.command.attemptId
      ),
      forceSettleAckMatches: ({ context, event }) => (
        commandCorrelationMatches(context, event)
      ),
    },
    actions: {
      markNaturalIdle: assign({ settledBy: "natural-idle" }),
      markForcedSettle: assign({ settledBy: "forced-settle" }),
      recordForcedFailure: assign(({ context, event }) => ({
        failure: event.type === "CHARACTER.FAILED"
          ? Object.freeze({
              kind: event.timedOut ? "force-settle-timeout" : "force-settle-failed",
              error: event.error,
              command: context.command,
            })
          : context.failure,
      })),
      recordForcedTimeout: assign(({ context }) => ({
        failure: timeoutFailure(context),
      })),
    },
  }).createMachine({
    id: "character-settle-workflow",
    initial: "naturallySettling",
    context: ({ input }) => createInitialContext(input),
    output: ({ event }) => {
      if (!("output" in event) || !event.output) {
        throw new Error("Character settle workflow completed without an output.");
      }
      return event.output as CharacterSettleMachineOutput;
    },
    states: {
      naturallySettling: {
        tags: ["character-settle-natural"],
        after: {
          naturalSettleTimeout: "issuingForceSettle",
        },
        on: {
          "MOTION.VISUAL_IDLE": {
            guard: "visualIdleMatches",
            target: "settled",
            actions: "markNaturalIdle",
          },
        },
      },
      issuingForceSettle: {
        tags: ["character-settle-command-pending"],
        on: {
          "MOTION.VISUAL_IDLE": {
            guard: "visualIdleMatches",
            target: "settled",
            actions: "markNaturalIdle",
          },
          "CHARACTER.SETTLE.COMMAND_DISPATCHED": {
            guard: "dispatchMatches",
            target: "awaitingForceSettleAck",
          },
        },
      },
      awaitingForceSettleAck: {
        tags: ["character-settle-forced"],
        after: {
          forcedSettleAckTimeout: {
            target: "failed",
            actions: "recordForcedTimeout",
          },
        },
        on: {
          "MOTION.VISUAL_IDLE": {
            guard: "visualIdleMatches",
            target: "settled",
            actions: "markNaturalIdle",
          },
          "CHARACTER.SETTLED": {
            guard: "forceSettleAckMatches",
            target: "settled",
            actions: "markForcedSettle",
          },
          "CHARACTER.FAILED": {
            guard: "forceSettleAckMatches",
            target: "failed",
            actions: "recordForcedFailure",
          },
        },
      },
      settled: {
        type: "final",
        output: ({ context }) => {
          if (!context.settledBy) {
            throw new Error("Settled character workflow is missing its settle source.");
          }
          return Object.freeze({
            status: "settled" as const,
            motionToken: context.motionToken,
            transactionId: context.transactionId,
            motionOperationId: context.motionOperationId,
            arrivedNodeId: context.arrivedNodeId,
            settledBy: context.settledBy,
          });
        },
      },
      failed: {
        type: "final",
        output: ({ context }) => {
          if (!context.failure) {
            throw new Error("Failed character workflow is missing failure details.");
          }
          return Object.freeze({
            status: "failed" as const,
            motionToken: context.motionToken,
            transactionId: context.transactionId,
            motionOperationId: context.motionOperationId,
            motionAttempt: context.motionAttempt,
            arrivedNodeId: context.arrivedNodeId,
            failure: context.failure,
          });
        },
      },
    },
  });
}

export type CharacterSettleMachineLogic = ReturnType<typeof createCharacterSettleMachine>;
export type CharacterSettleMachineSnapshot = SnapshotFrom<CharacterSettleMachineLogic>;
