import type {
  LearningPathEvent,
  LearningPathMachineContext,
  LearningPathMachineInput,
} from "../domain/orchestrationTypes";

type RecoveryCompleteEvent = Extract<
  LearningPathEvent,
  { readonly type: "ORCHESTRATION.RECOVERY.COMPLETE" }
>;

function createEmptyNavigationContext(): Pick<
  LearningPathMachineContext,
  | "requestedTargetNodeId"
  | "queuedTargetNodeId"
  | "navigationPlan"
  | "navigationStageIndex"
  | "navigationBeforeActionIndex"
  | "navigationAfterActionIndex"
  | "navigationCommandToken"
  | "navigationCommandAttempt"
  | "motionCommandToken"
  | "navigationStageStartedCommitted"
  | "arrivedNodeId"
  | "linkedZoneCleanupComplete"
  | "navigationWorkflowPhase"
  | "navigationWorkflowCommand"
  | "navigationLinkedCleanupCorrelation"
  | "navigationLinkedCleanupPlanId"
> {
  return {
    requestedTargetNodeId: null,
    queuedTargetNodeId: null,
    navigationPlan: null,
    navigationStageIndex: 0,
    navigationBeforeActionIndex: 0,
    navigationAfterActionIndex: 0,
    navigationCommandToken: null,
    navigationCommandAttempt: 1,
    motionCommandToken: null,
    navigationStageStartedCommitted: false,
    arrivedNodeId: null,
    linkedZoneCleanupComplete: true,
    navigationWorkflowPhase: "idle",
    navigationWorkflowCommand: null,
    navigationLinkedCleanupCorrelation: null,
    navigationLinkedCleanupPlanId: null,
  };
}

function createEmptyZoneContext(): Pick<
  LearningPathMachineContext,
  | "zoneRevealPlan"
  | "zoneRevealBeforeActionIndex"
  | "zoneRevealStepIndex"
  | "zoneRevealCommandToken"
  | "zoneRevealCommandAttempt"
  | "zoneDismissPlan"
  | "zoneDismissStepIndex"
  | "zoneDismissCommandToken"
  | "zoneDismissCommandAttempt"
  | "zoneTransitionActive"
> {
  return {
    zoneRevealPlan: null,
    zoneRevealBeforeActionIndex: 0,
    zoneRevealStepIndex: 0,
    zoneRevealCommandToken: null,
    zoneRevealCommandAttempt: 1,
    zoneDismissPlan: null,
    zoneDismissStepIndex: 0,
    zoneDismissCommandToken: null,
    zoneDismissCommandAttempt: 1,
    zoneTransitionActive: false,
  };
}

export function createInitialLearningPathContext(
  input: LearningPathMachineInput,
): LearningPathMachineContext {
  return {
    zoneInitiallyActive: input.initialZoneStatus === "active",
    navigationEpochBase: input.navigationEpoch ?? `navigation:${input.initialNodeId}`,
    navigationEpochRevision: 1,
    navigationSequence: 0,
    pendingNavigationTargetNodeId: null,
    currentNodeId: input.initialNodeId,
    ...createEmptyNavigationContext(),
    ...createEmptyZoneContext(),
    characterVisualIdle: input.initialCharacterVisualIdle ?? true,
    fatalError: null,
    recoveryRequest: null,
    lastRecovery: null,
    lastRejectedNavigation: null,
  };
}

/**
 * Restores all transactional slices after a successful durable recovery.
 * The queued navigation intent is deliberately omitted so XState's partial
 * assign preserves the latest intent received while recovery was active.
 */
export function createRecoveredLearningPathContext(
  context: LearningPathMachineContext,
  event: RecoveryCompleteEvent,
): Partial<LearningPathMachineContext> {
  const navigation = createEmptyNavigationContext();
  const { queuedTargetNodeId: _preservedQueue, ...resetNavigation } = navigation;
  return {
    zoneInitiallyActive: event.zoneStatus === "active",
    navigationEpochRevision: context.navigationEpochRevision + 1,
    pendingNavigationTargetNodeId: context.pendingNavigationTargetNodeId,
    navigationSequence: context.navigationSequence,
    currentNodeId: event.nodeId,
    ...resetNavigation,
    ...createEmptyZoneContext(),
    characterVisualIdle: true,
    fatalError: null,
    recoveryRequest: null,
    queuedTargetNodeId: context.pendingNavigationTargetNodeId,
    lastRecovery: Object.freeze({
      recoveryId: event.recoveryId,
      transactionId: event.transactionId,
      nodeId: event.nodeId,
      zoneStatus: event.zoneStatus,
      compensatedOperationCount: event.compensatedOperationCount,
    }),
  };
}
