import { assign, setup } from "xstate";
import type {
  RecoveryCommand,
  RecoveryContext,
  RecoveryCorrelation,
  RecoveryEvent,
  RecoveryFailure,
  RecoveryJournalEntry,
  RecoveryMachineInput,
  RecoveryMachineOutput,
  RecoveryMachineOptions,
  RecoveryStep,
} from "./types";

const DEFAULT_COMMAND_TIMEOUT_MS = 8_000;
const DEFAULT_CHARACTER_IDLE_TIMEOUT_MS = 4_000;

function immutableEntry(entry: RecoveryJournalEntry): RecoveryJournalEntry {
  return Object.freeze({
    ...entry,
    metadata: Object.freeze({ ...entry.metadata }),
  });
}

function requireNonEmpty(value: string, label: string): string {
  if (value.length === 0) throw new Error(`${label} must be non-empty.`);
  return value;
}

function createInitialContext(input: RecoveryMachineInput): RecoveryContext {
  if (!Number.isSafeInteger(input.sessionRevision) || input.sessionRevision < 0) {
    throw new Error("sessionRevision must be a non-negative safe integer.");
  }
  const journalIds = new Set<string>();
  const journal = input.journal.map((entry) => {
    requireNonEmpty(entry.journalId, "journalId");
    if (journalIds.has(entry.journalId)) {
      throw new Error(`Duplicate recovery journal id \"${entry.journalId}\".`);
    }
    journalIds.add(entry.journalId);
    return immutableEntry(entry);
  });
  return Object.freeze({
    recoveryId: requireNonEmpty(input.recoveryId, "recoveryId"),
    sessionRevision: input.sessionRevision,
    transactionId: requireNonEmpty(input.transactionId, "transactionId"),
    checkpointId: requireNonEmpty(input.checkpointId, "checkpointId"),
    safeNodeId: requireNonEmpty(input.safeNodeId, "safeNodeId"),
    journal: Object.freeze(journal),
    cursor: journal.length - 1,
    compensatedOperationCount: 0,
    failure: null,
  });
}

function correlation(
  context: RecoveryContext,
  operationSuffix: string,
): RecoveryCorrelation {
  const operationId = `${context.recoveryId}:${operationSuffix}`;
  return Object.freeze({
    recoveryId: context.recoveryId,
    sessionRevision: context.sessionRevision,
    transactionId: context.transactionId,
    operationId,
    attemptId: `${operationId}:attempt:1`,
    attempt: 1,
  });
}

export function commandForStep(
  context: RecoveryContext,
  step: RecoveryStep,
): RecoveryCommand | null {
  if (step === "cancelling-presentation") {
    return Object.freeze({
      type: "RECOVERY.CANCEL_PRESENTATION",
      step,
      ...correlation(context, "cancel-presentation"),
    });
  }
  if (step === "aborting-motion") {
    return Object.freeze({
      type: "RECOVERY.ABORT_MOTION",
      step,
      safeNodeId: context.safeNodeId,
      ...correlation(context, "abort-motion"),
    });
  }
  if (step === "compensating") {
    const entry = context.journal[context.cursor];
    if (!entry) return null;
    return Object.freeze({
      type: "RECOVERY.COMPENSATE_PRESENTATION",
      step,
      journalIndex: context.cursor,
      entry,
      ...correlation(context, `compensate:${context.cursor}:${entry.journalId}`),
    });
  }
  if (step === "restoring-rule-ledger") {
    return Object.freeze({
      type: "RECOVERY.RESTORE_RULE_LEDGER",
      step,
      checkpointId: context.checkpointId,
      ...correlation(context, "restore-rule-ledger"),
    });
  }
  return Object.freeze({
    type: "RECOVERY.AWAIT_CHARACTER_IDLE",
    step,
    safeNodeId: context.safeNodeId,
    ...correlation(context, "await-character-idle"),
  });
}

function sameCorrelation(
  event: RecoveryEvent,
  command: RecoveryCommand | null,
): boolean {
  return command !== null
    && event.type !== "RECOVERY.RESET"
    && event.recoveryId === command.recoveryId
    && event.sessionRevision === command.sessionRevision
    && event.transactionId === command.transactionId
    && event.operationId === command.operationId
    && event.attemptId === command.attemptId
    && event.attempt === command.attempt;
}

function failureFromCommand(
  command: RecoveryCommand,
  kind: RecoveryFailure["kind"],
  error: string,
): RecoveryFailure {
  const {
    recoveryId,
    sessionRevision,
    transactionId,
    operationId,
    attemptId,
    attempt,
  } = command;
  return Object.freeze({
    kind,
    step: command.step,
    commandType: command.type,
    error,
    correlation: Object.freeze({
      recoveryId,
      sessionRevision,
      transactionId,
      operationId,
      attemptId,
      attempt,
    }),
  });
}

function failedEventError(event: RecoveryEvent): string {
  return event.type === "RECOVERY.COMMAND.FAILED"
    ? event.error
    : "Recovery command failed.";
}

function failureAssignment(
  context: RecoveryContext,
  event: RecoveryEvent,
  step: RecoveryStep,
): Partial<RecoveryContext> {
  const command = commandForStep(context, step);
  return command
    ? { failure: failureFromCommand(command, "command-failed", failedEventError(event)) }
    : {};
}

function timeoutAssignment(
  context: RecoveryContext,
  step: RecoveryStep,
): Partial<RecoveryContext> {
  const command = commandForStep(context, step);
  return command
    ? {
      failure: failureFromCommand(
        command,
        "timeout",
        `${command.type} timed out.`,
      ),
    }
    : {};
}

/**
 * Serializable recovery workflow. The runtime observes the selected command,
 * executes it through an adapter, and sends a fully correlated ACK back.
 */
export function createRecoveryMachine(options: RecoveryMachineOptions = {}) {
  const commandTimeoutMs = options.commandTimeoutMs ?? DEFAULT_COMMAND_TIMEOUT_MS;
  const characterIdleTimeoutMs = options.characterIdleTimeoutMs
    ?? DEFAULT_CHARACTER_IDLE_TIMEOUT_MS;
  if (!Number.isFinite(commandTimeoutMs) || commandTimeoutMs < 0) {
    throw new Error("commandTimeoutMs must be a finite non-negative number.");
  }
  if (!Number.isFinite(characterIdleTimeoutMs) || characterIdleTimeoutMs < 0) {
    throw new Error("characterIdleTimeoutMs must be a finite non-negative number.");
  }

  return setup({
    types: {} as {
      context: RecoveryContext;
      events: RecoveryEvent;
      input: RecoveryMachineInput;
      output: RecoveryMachineOutput;
    },
    delays: {
      recoveryCommandTimeout: commandTimeoutMs,
      recoveryCharacterIdleTimeout: characterIdleTimeoutMs,
    },
    guards: {
      noCompensationRemaining: ({ context }) => context.cursor < 0,
      cancelAckMatches: ({ context, event }) => sameCorrelation(
        event,
        commandForStep(context, "cancelling-presentation"),
      ),
      abortAckMatches: ({ context, event }) => sameCorrelation(
        event,
        commandForStep(context, "aborting-motion"),
      ),
      compensationAckMatches: ({ context, event }) => sameCorrelation(
        event,
        commandForStep(context, "compensating"),
      ),
      restoreAckMatches: ({ context, event }) => sameCorrelation(
        event,
        commandForStep(context, "restoring-rule-ledger"),
      ),
      characterIdleAckMatches: ({ context, event }) => sameCorrelation(
        event,
        commandForStep(context, "awaiting-character-idle"),
      ),
    },
    actions: {
      advanceCompensation: assign(({ context }) => ({
        cursor: context.cursor - 1,
        compensatedOperationCount: context.compensatedOperationCount + 1,
      })),
      finishCompensation: assign(({ context }) => ({
        cursor: -1,
        compensatedOperationCount: context.compensatedOperationCount + 1,
      })),
      closeRecovery: assign(() => ({ failure: null })),
      recordCancelFailure: assign(({ context, event }) => (
        failureAssignment(context, event, "cancelling-presentation")
      )),
      recordAbortFailure: assign(({ context, event }) => (
        failureAssignment(context, event, "aborting-motion")
      )),
      recordCompensationFailure: assign(({ context, event }) => (
        failureAssignment(context, event, "compensating")
      )),
      recordRestoreFailure: assign(({ context, event }) => (
        failureAssignment(context, event, "restoring-rule-ledger")
      )),
      recordCharacterFailure: assign(({ context, event }) => (
        failureAssignment(context, event, "awaiting-character-idle")
      )),
      recordCancelTimeout: assign(({ context }) => (
        timeoutAssignment(context, "cancelling-presentation")
      )),
      recordAbortTimeout: assign(({ context }) => (
        timeoutAssignment(context, "aborting-motion")
      )),
      recordCompensationTimeout: assign(({ context }) => (
        timeoutAssignment(context, "compensating")
      )),
      recordRestoreTimeout: assign(({ context }) => (
        timeoutAssignment(context, "restoring-rule-ledger")
      )),
      recordCharacterTimeout: assign(({ context }) => (
        timeoutAssignment(context, "awaiting-character-idle")
      )),
    },
  }).createMachine({
    id: "recovery-workflow",
    initial: "preparing",
    context: ({ input }) => createInitialContext(input),
    output: ({ event }) => {
      if (!("output" in event) || !event.output) {
        throw new Error("Recovery workflow completed without a terminal output.");
      }
      return event.output as RecoveryMachineOutput;
    },
    on: {
      "RECOVERY.RESET": {
        target: ".closed",
        actions: "closeRecovery",
      },
    },
    states: {
      preparing: {
        always: "cancellingPresentation",
      },
      cancellingPresentation: {
        tags: ["recovery-command-pending"],
        after: {
          recoveryCommandTimeout: {
            target: "failed",
            actions: "recordCancelTimeout",
          },
        },
        on: {
          "RECOVERY.COMMAND.SUCCEEDED": {
            guard: "cancelAckMatches",
            target: "abortingMotion",
          },
          "RECOVERY.COMMAND.FAILED": {
            guard: "cancelAckMatches",
            target: "failed",
            actions: "recordCancelFailure",
          },
        },
      },
      abortingMotion: {
        tags: ["recovery-command-pending"],
        after: {
          recoveryCommandTimeout: {
            target: "failed",
            actions: "recordAbortTimeout",
          },
        },
        on: {
          "RECOVERY.COMMAND.SUCCEEDED": {
            guard: "abortAckMatches",
            target: "compensating",
          },
          "RECOVERY.COMMAND.FAILED": {
            guard: "abortAckMatches",
            target: "failed",
            actions: "recordAbortFailure",
          },
        },
      },
      compensating: {
        tags: ["recovery-command-pending"],
        always: {
          guard: "noCompensationRemaining",
          target: "restoringRuleLedger",
        },
        after: {
          recoveryCommandTimeout: {
            target: "failed",
            actions: "recordCompensationTimeout",
          },
        },
        on: {
          "RECOVERY.COMMAND.SUCCEEDED": [
            {
              guard: ({ context, event }) => (
                sameCorrelation(event, commandForStep(context, "compensating"))
                && context.cursor > 0
              ),
              target: "compensating",
              reenter: true,
              actions: "advanceCompensation",
            },
            {
              guard: "compensationAckMatches",
              target: "restoringRuleLedger",
              actions: "finishCompensation",
            },
          ],
          "RECOVERY.COMMAND.FAILED": {
            guard: "compensationAckMatches",
            target: "failed",
            actions: "recordCompensationFailure",
          },
        },
      },
      restoringRuleLedger: {
        tags: ["recovery-command-pending"],
        after: {
          recoveryCommandTimeout: {
            target: "failed",
            actions: "recordRestoreTimeout",
          },
        },
        on: {
          "RECOVERY.COMMAND.SUCCEEDED": {
            guard: "restoreAckMatches",
            target: "awaitingCharacterIdle",
          },
          "RECOVERY.COMMAND.FAILED": {
            guard: "restoreAckMatches",
            target: "failed",
            actions: "recordRestoreFailure",
          },
        },
      },
      awaitingCharacterIdle: {
        tags: ["recovery-command-pending"],
        after: {
          recoveryCharacterIdleTimeout: {
            target: "failed",
            actions: "recordCharacterTimeout",
          },
        },
        on: {
          "RECOVERY.COMMAND.SUCCEEDED": {
            guard: "characterIdleAckMatches",
            target: "succeeded",
          },
          "RECOVERY.COMMAND.FAILED": {
            guard: "characterIdleAckMatches",
            target: "failed",
            actions: "recordCharacterFailure",
          },
        },
      },
      succeeded: {
        type: "final",
        tags: ["recovery-succeeded"],
        output: ({ context }) => Object.freeze({
          status: "succeeded" as const,
          recoveryId: context.recoveryId,
          safeNodeId: context.safeNodeId,
          compensatedOperationCount: context.compensatedOperationCount,
        }),
      },
      failed: {
        type: "final",
        tags: ["recovery-degraded"],
        output: ({ context }) => {
          if (!context.failure) {
            throw new Error("A failed recovery must include failure details.");
          }
          return Object.freeze({
            status: "degraded" as const,
            recoveryId: context.recoveryId,
            safeNodeId: context.safeNodeId,
            failure: context.failure,
          });
        },
      },
      closed: {
        type: "final",
        tags: ["recovery-closed"],
        output: ({ context }) => Object.freeze({
          status: "closed" as const,
          recoveryId: context.recoveryId,
        }),
      },
    },
  });
}

export type RecoveryMachineLogic = ReturnType<typeof createRecoveryMachine>;
