import type { LearningPathMachineContext } from "../../domain/orchestrationTypes";
import type { NavigationPhase } from "../../../workflows/navigation";

const phaseTargets: Readonly<Record<NavigationPhase, string>> = Object.freeze({
  idle: ".idle",
  planning: ".planning",
  "before-bridge": ".beforeBridge",
  moving: ".moving",
  "after-arrival-bridge": ".afterArrivalBridge",
  "awaiting-character-settle": ".awaitingSettle",
  "awaiting-linked-cleanup": ".awaitingSettle",
  failed: ".failed",
});

const projectionTransitions = (Object.keys(phaseTargets) as NavigationPhase[])
  .map((phase) => ({
    guard: { type: "navigationPhaseMatches" as const, params: { phase } },
    target: phaseTargets[phase] as `.${string}`,
  }));

/**
 * Backwards-compatible state-ID/tag projection of the real Navigation actor.
 * There is intentionally no planner, commit, retry, presentation, motion, or
 * character-settle command source in this region.
 */
export const navigationRegion = {
  initial: "initializing",
  invoke: {
    id: "navigationWorkflow",
    src: "navigationWorkflow",
    input: ({ context }: { readonly context: LearningPathMachineContext }) => {
      const epoch = `${context.navigationEpochBase}:epoch:${context.navigationEpochRevision}`;
      const operationId = `${epoch}:child-lifecycle`;
      return {
        correlation: {
          epoch,
          sequence: context.navigationSequence,
          transactionId: `${epoch}:session`,
          operationId,
          attemptId: `${operationId}:attempt:1`,
          attempt: 1,
        },
        initialNodeId: context.currentNodeId,
        initialCharacterVisualIdle: context.characterVisualIdle,
      };
    },
    onSnapshot: {
      actions: ["syncNavigationSnapshot", "raiseNavigationProjection"],
    },
  },
  on: {
    "ORCHESTRATION.NAVIGATION.PHASE_CHANGED": projectionTransitions,
    "NAVIGATION.REQUESTED": { actions: "routeOrQueueNavigationIntent" },
    "PRESENTATION.SETTLED": {
      guard: "navigationPresentationEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "PRESENTATION.FAILED": {
      guard: "navigationPresentationEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "PRESENTATION.TIMED_OUT": {
      guard: "navigationPresentationEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "MOTION.DEPARTED": {
      guard: "navigationMotionEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "MOTION.ARRIVED": {
      guard: "navigationMotionEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "MOTION.VISUAL_IDLE": {
      guard: "navigationMotionEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "MOTION.FAILED": {
      guard: "navigationMotionEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "MOTION.TIMED_OUT": {
      guard: "navigationMotionEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "CHARACTER.SETTLED": {
      guard: "navigationCharacterEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "CHARACTER.FAILED": {
      guard: "navigationCharacterEventRelevant",
      actions: "forwardNavigationGatewayEvent",
    },
    "NAVIGATION.LINKED_ZONE_CLEANUP.REQUESTED": {
      actions: "armLinkedZoneCleanup",
    },
    "NAVIGATION.SETTLED": { actions: "notifyNavigationSettled" },
    "NAVIGATION.REJECTED": { actions: "notifyNavigationRejected" },
  },
  states: {
    initializing: {},
    idle: {
      tags: ["navigation-idle"],
      always: {
        guard: "canFlushPendingNavigation",
        actions: "flushPendingNavigationIntent",
      },
    },
    planning: { tags: ["navigation-busy", "navigation-planning"] },
    selectingBeforeAction: { tags: ["navigation-busy", "navigation-planning"] },
    beforeBridge: { tags: ["navigation-busy", "navigation-before-bridge"] },
    moving: { tags: ["navigation-busy", "navigation-moving"] },
    selectingAfterAction: { tags: ["navigation-busy", "navigation-after-arrival"] },
    afterArrivalBridge: { tags: ["navigation-busy", "navigation-after-arrival"] },
    completingStage: { tags: ["navigation-busy", "navigation-after-arrival"] },
    awaitingSettle: { tags: ["navigation-busy", "navigation-awaiting-settle"] },
    failed: { tags: ["navigation-failed"] },
  },
} as const;
