import type {
  BridgeTransitionAction,
  NavigationPlan,
  ZoneDismissPlan,
  ZoneRevealPlan,
} from "../../simulation/PathRuleCoordinator";
import type {
  BridgePresentationCommand,
  ConstructPresentationCommand,
  MotionCommand,
  PresentationLane,
} from "./orchestrationTypes";

export function navigationBridgeToken(
  planId: string,
  stageIndex: number,
  timing: "before" | "after",
  actionIndex: number,
): string {
  return `nav:${planId}:stage:${stageIndex}:${timing}:${actionIndex}`;
}

export function zoneRevealBeforeToken(planId: string, actionIndex: number): string {
  return `zone:${planId}:reveal-before:${actionIndex}`;
}

export function zoneRevealStepToken(planId: string, stepIndex: number): string {
  return `zone:${planId}:reveal:${stepIndex}`;
}

export function zoneDismissStepToken(planId: string, stepIndex: number): string {
  return `zone:${planId}:dismiss:${stepIndex}`;
}

export function motionToken(
  planId: string,
  stageIndex: number,
  stageId: string,
): string {
  return `motion:${planId}:stage:${stageIndex}:${stageId}`;
}

export function attemptToken(operationId: string, attempt: number): string {
  return `${operationId}:attempt:${attempt}`;
}

export function bridgeCommand(
  operationId: string,
  attempt: number,
  lane: PresentationLane,
  planId: string,
  stepIndex: number,
  action: BridgeTransitionAction,
): BridgePresentationCommand {
  const transactionId = planId;
  const token = attemptToken(operationId, attempt);
  return Object.freeze({
    type: "PRESENTATION.BRIDGE",
    token,
    transactionId,
    operationId,
    attemptId: token,
    attempt,
    lane,
    planId,
    stepIndex,
    action,
  });
}

export function revealStepCommand(
  plan: ZoneRevealPlan,
  stepIndex: number,
  attempt = 1,
): BridgePresentationCommand | ConstructPresentationCommand {
  const step = plan.steps[stepIndex];
  if (!step) {
    throw new Error(`Reveal plan "${plan.id}" has no step ${stepIndex}.`);
  }
  const operationId = zoneRevealStepToken(plan.id, stepIndex);
  const token = attemptToken(operationId, attempt);
  if (step.source.kind === "bridge") {
    if (!step.bridgeAction) {
      throw new Error(`Reveal bridge step ${stepIndex} has no bridge action.`);
    }
    return bridgeCommand(operationId, attempt, "zone-reveal", plan.id, stepIndex, step.bridgeAction);
  }
  return Object.freeze({
    type: "PRESENTATION.CONSTRUCT",
    token,
    transactionId: plan.id,
    operationId,
    attemptId: token,
    attempt,
    lane: "zone-reveal",
    planId: plan.id,
    stepIndex,
    direction: "fall-in",
    construct: step.source,
  });
}

export function dismissStepCommand(
  plan: ZoneDismissPlan,
  stepIndex: number,
  attempt = 1,
  linkedNavigationTransactionId?: string | null,
): BridgePresentationCommand | ConstructPresentationCommand {
  const step = plan.steps[stepIndex];
  if (!step) {
    throw new Error(`Dismiss plan "${plan.id}" has no step ${stepIndex}.`);
  }
  const transactionId = linkedNavigationTransactionId
    ?? plan.linkedNavigationPlanId
    ?? plan.id;
  const operationId = zoneDismissStepToken(plan.id, stepIndex);
  const token = attemptToken(operationId, attempt);
  if (step.source.kind === "bridge") {
    if (!step.bridgeAction) {
      throw new Error(`Dismiss bridge step ${stepIndex} has no bridge action.`);
    }
    return Object.freeze({
      ...bridgeCommand(operationId, attempt, "zone-dismiss", transactionId, stepIndex, step.bridgeAction),
      planId: plan.id,
    });
  }
  return Object.freeze({
    type: "PRESENTATION.CONSTRUCT",
    token,
    transactionId,
    operationId,
    attemptId: token,
    attempt,
    lane: "zone-dismiss",
    planId: plan.id,
    stepIndex,
    direction: "rise-out",
    construct: step.source,
  });
}

export function navigationMotionCommand(
  plan: NavigationPlan,
  stageIndex: number,
  attempt = 1,
): MotionCommand {
  const stage = plan.stages[stageIndex];
  if (!stage) {
    throw new Error(`Navigation plan "${plan.id}" has no stage ${stageIndex}.`);
  }
  const operationId = motionToken(plan.id, stageIndex, stage.id);
  const token = attemptToken(operationId, attempt);
  return Object.freeze({
    type: "MOTION.NAVIGATE",
    token,
    transactionId: plan.id,
    operationId,
    attemptId: token,
    attempt,
    navigationPlanId: plan.id,
    stageId: stage.id,
    stageIndex,
    fromNodeId: stage.fromNodeId,
    toNodeId: stage.toNodeId,
    routeNodeIds: stage.routeNodeIds,
    routeEdgeIds: stage.routeEdgeIds,
  });
}
