import { fromCallback } from "xstate";
import type {
  CharacterFailedAck,
  MotionFailedAck,
  PresentationFailedAck,
  SceneRuntimeCorrelation,
  SceneRuntimeGatewayAck,
  SceneRuntimeGatewayCommand,
  SceneRuntimeGatewayInput,
  SceneRuntimeGatewayScheduler,
  SceneRuntimePortAck,
  SceneRuntimeDispatchReceipt,
} from "./types";

const DEFAULT_TIMEOUT_MS = 15_000;
const MAX_RETAINED_ATTEMPT_WATERMARKS = 512;

interface ActiveAttempt {
  readonly kind: "presentation" | "motion" | "character";
  readonly correlation: SceneRuntimeCorrelation;
  readonly timeoutMs: number;
  cancel: (() => void) | null;
  timer: ReturnType<typeof globalThis.setTimeout> | null;
  phase:
    | "waiting-start"
    | "running"
    | "waiting-visual-idle";
}

interface AttemptWatermark {
  readonly attempt: number;
  readonly attemptId: string;
}

function correlationOf(
  value: SceneRuntimeCorrelation,
): SceneRuntimeCorrelation {
  return Object.freeze({
    sessionRevision: value.sessionRevision,
    transactionId: value.transactionId,
    operationId: value.operationId,
    attemptId: value.attemptId,
    attempt: value.attempt,
  });
}

function operationKey(correlation: SceneRuntimeCorrelation): string {
  return `${correlation.transactionId}\u0000${correlation.operationId}`;
}

function watermarkKey(command: SceneRuntimeGatewayCommand): string {
  return `${command.type}\u0000${operationKey(command)}`;
}

function activeKey(
  kind: ActiveAttempt["kind"],
  correlation: SceneRuntimeCorrelation,
): string {
  return `${kind}\u0000${operationKey(correlation)}`;
}

function sameAttempt(
  left: SceneRuntimeCorrelation,
  right: SceneRuntimeCorrelation,
): boolean {
  return left.sessionRevision === right.sessionRevision
    && left.transactionId === right.transactionId
    && left.operationId === right.operationId
    && left.attemptId === right.attemptId
    && left.attempt === right.attempt;
}

function attemptKind(
  command: SceneRuntimeGatewayCommand,
): ActiveAttempt["kind"] | null {
  if (command.type === "PRESENTATION.EXECUTE") return "presentation";
  if (command.type === "MOTION.EXECUTE") return "motion";
  if (command.type === "CHARACTER.FORCE_SETTLE") return "character";
  return null;
}

function ackKind(ack: SceneRuntimePortAck): ActiveAttempt["kind"] {
  if (ack.type.startsWith("PRESENTATION.")) return "presentation";
  if (ack.type.startsWith("MOTION.")) return "motion";
  return "character";
}

function isTerminalAck(ack: SceneRuntimePortAck): boolean {
  return ack.type === "PRESENTATION.SETTLED"
    || ack.type === "PRESENTATION.FAILED"
    || ack.type === "MOTION.VISUAL_IDLE"
    || ack.type === "MOTION.FAILED"
    || ack.type === "CHARACTER.SETTLED"
    || ack.type === "CHARACTER.FAILED";
}

function acceptedAck(
  kind: ActiveAttempt["kind"],
  correlation: SceneRuntimeCorrelation,
): SceneRuntimeGatewayAck {
  return {
    type: kind === "presentation"
      ? "PRESENTATION.ACCEPTED"
      : kind === "motion"
        ? "MOTION.ACCEPTED"
        : "CHARACTER.ACCEPTED",
    ...correlation,
  } as SceneRuntimeGatewayAck;
}

function timedOutAck(active: ActiveAttempt):
  | PresentationFailedAck
  | MotionFailedAck
  | CharacterFailedAck {
  const common = {
    ...active.correlation,
    error: `${active.kind} attempt timed out.`,
    timedOut: true,
  };
  if (active.kind === "presentation") {
    return { type: "PRESENTATION.FAILED", ...common };
  }
  if (active.kind === "motion") {
    return { type: "MOTION.FAILED", ...common };
  }
  return { type: "CHARACTER.FAILED", ...common };
}

function thrownAck(
  kind: ActiveAttempt["kind"],
  correlation: SceneRuntimeCorrelation,
  error: unknown,
): PresentationFailedAck | MotionFailedAck | CharacterFailedAck {
  const common = {
    ...correlation,
    error: error instanceof Error ? error.message : String(error),
  };
  if (kind === "presentation") {
    return { type: "PRESENTATION.FAILED", ...common };
  }
  if (kind === "motion") {
    return { type: "MOTION.FAILED", ...common };
  }
  return { type: "CHARACTER.FAILED", ...common };
}

function normalizeCleanup(
  cleanup: (() => void) | { readonly unsubscribe: () => void },
): () => void {
  return typeof cleanup === "function"
    ? cleanup
    : () => cleanup.unsubscribe();
}

/**
 * Creates the single XState boundary to an imperative scene runtime.
 *
 * The gateway only transports coarse commands and lifecycle acknowledgements;
 * animation frames remain owned by the scene runtime and never enter XState.
 */
export function createSceneRuntimeGateway() {
  return fromCallback<SceneRuntimeGatewayCommand, SceneRuntimeGatewayInput>(({
    input,
    receive,
    sendBack,
  }) => {
    const scheduler: SceneRuntimeGatewayScheduler = input.scheduler ?? {
      setTimeout: (callback, delayMs) => globalThis.setTimeout(callback, delayMs),
      clearTimeout: (handle) => globalThis.clearTimeout(handle),
    };
    const defaultTimeoutMs = input.defaultTimeoutMs ?? DEFAULT_TIMEOUT_MS;
    const activeByOperation = new Map<string, ActiveAttempt>();
    const watermarks = new Map<string, AttemptWatermark>();
    const bufferedAcks: SceneRuntimePortAck[] = [];
    let dispatching = false;
    let disposed = false;
    let cleaned = false;

    const publish = (ack: SceneRuntimeGatewayAck): void => {
      if (!disposed) sendBack(ack);
    };

    const clearAttemptTimer = (active: ActiveAttempt): void => {
      if (active.timer === null) return;
      scheduler.clearTimeout(active.timer);
      active.timer = null;
    };

    const clearAttempt = (
      key: string,
      active: ActiveAttempt,
      invokeCancel: boolean,
    ): void => {
      clearAttemptTimer(active);
      if (invokeCancel && active.cancel) {
        const cancel = active.cancel;
        active.cancel = null;
        try {
          cancel();
        } catch {
          // Best-effort cleanup must never prevent the other attempts from
          // being cancelled during actor shutdown or transaction abort.
        }
      } else {
        active.cancel = null;
      }
      if (activeByOperation.get(key) === active) {
        activeByOperation.delete(key);
      }
    };

    const startAttemptTimer = (
      key: string,
      active: ActiveAttempt,
    ): void => {
      if (active.timeoutMs <= 0
        || active.timer !== null
        || activeByOperation.get(key) !== active) {
        return;
      }
      active.timer = scheduler.setTimeout(() => {
        if (disposed || activeByOperation.get(key) !== active) return;
        publish(timedOutAck(active));
        clearAttempt(key, active, true);
      }, active.timeoutMs);
    };

    const handlePortAck = (ack: SceneRuntimePortAck): void => {
      if (disposed || ack.sessionRevision !== input.sessionRevision) return;
      const kind = ackKind(ack);
      const key = activeKey(kind, ack);
      const active = activeByOperation.get(key);
      if (!active || active.kind !== kind || !sameAttempt(active.correlation, ack)) {
        return;
      }

      if (ack.type === "PRESENTATION.STARTED") {
        active.phase = "running";
        startAttemptTimer(key, active);
      } else if (ack.type === "MOTION.ARRIVED") {
        // ARRIVED ends route execution. VISUAL_IDLE belongs to the following
        // settle phase, which remains visible to the owning XState operation
        // without inheriting the route watchdog.
        clearAttemptTimer(active);
        active.phase = "waiting-visual-idle";
      }

      publish(ack);
      if (isTerminalAck(ack)) clearAttempt(key, active, false);
    };

    const onPortAck = (ack: SceneRuntimePortAck): void => {
      if (disposed) return;
      if (dispatching) {
        bufferedAcks.push(ack);
        return;
      }
      handlePortAck(ack);
    };

    const subscriptionCleanup = normalizeCleanup(input.port.subscribe(onPortAck));

    const reject = (
      command: SceneRuntimeGatewayCommand,
      reason: "stale-session" | "stale-attempt" | "attempt-id-conflict" | "disposed",
    ): void => {
      publish({ type: "SCENE_RUNTIME.COMMAND_REJECTED", ...correlationOf(command), reason });
    };

    const rememberWatermark = (
      key: string,
      watermark: AttemptWatermark,
    ): void => {
      // Preserve insertion order as a small LRU. We retain completed attempts
      // long enough to reject late duplicate deliveries without allowing an
      // unbounded command history to accumulate during a long-running page.
      watermarks.delete(key);
      watermarks.set(key, watermark);
      while (watermarks.size > MAX_RETAINED_ATTEMPT_WATERMARKS) {
        const oldestKey = watermarks.keys().next().value as string | undefined;
        if (oldestKey === undefined) break;
        watermarks.delete(oldestKey);
      }
    };

    const validateAttempt = (command: SceneRuntimeGatewayCommand): boolean => {
      if (disposed) {
        reject(command, "disposed");
        return false;
      }
      if (command.sessionRevision !== input.sessionRevision) {
        reject(command, "stale-session");
        return false;
      }
      const key = watermarkKey(command);
      const watermark = watermarks.get(key);
      if (!watermark) return true;
      if (command.attempt < watermark.attempt) {
        reject(command, "stale-attempt");
        return false;
      }
      if (command.attempt === watermark.attempt) {
        if (command.attemptId !== watermark.attemptId) {
          reject(command, "attempt-id-conflict");
        }
        // Exact re-delivery is deliberately idempotent and is not dispatched
        // twice. The existing attempt will produce its original ACK stream.
        return false;
      }
      return true;
    };

    const cancelMatching = (
      predicate: (attempt: ActiveAttempt) => boolean,
    ): void => {
      [...activeByOperation.entries()].forEach(([key, active]) => {
        if (predicate(active)) clearAttempt(key, active, true);
      });
    };

    const dispatchControl = (command: SceneRuntimeGatewayCommand): void => {
      try {
        input.port.dispatch(command);
      } catch {
        // Cancellation/abort are idempotent cleanup controls. Their failure is
        // intentionally not promoted into a new business operation.
      }
    };

    const dispatchAttempt = (
      command: SceneRuntimeGatewayCommand,
      kind: ActiveAttempt["kind"],
    ): void => {
      const key = activeKey(kind, command);
      const previous = activeByOperation.get(key);
      if (previous) clearAttempt(key, previous, true);

      const correlation = correlationOf(command);
      const requestedTimeout = "timeoutMs" in command ? command.timeoutMs : undefined;
      const timeoutMs = requestedTimeout ?? defaultTimeoutMs;
      const active: ActiveAttempt = {
        kind,
        correlation,
        timeoutMs,
        cancel: null,
        timer: null,
        phase: "running",
      };
      activeByOperation.set(key, active);
      rememberWatermark(watermarkKey(command), {
        attempt: command.attempt,
        attemptId: command.attemptId,
      });

      publish(acceptedAck(kind, correlation));
      let receipt: SceneRuntimeDispatchReceipt | void;
      dispatching = true;
      try {
        receipt = input.port.dispatch(command);
      } catch (error) {
        dispatching = false;
        publish(thrownAck(kind, correlation, error));
        clearAttempt(key, active, false);
        bufferedAcks.splice(0).forEach(handlePortAck);
        return;
      }
      dispatching = false;

      if (receipt?.cancel) active.cancel = receipt.cancel;
      if (kind === "presentation" && receipt?.disposition === "deferred") {
        active.phase = "waiting-start";
        publish({
          type: "PRESENTATION.DEFERRED",
          ...correlation,
          reason: receipt.deferredReason,
        });
      }

      if (active.phase === "running") {
        startAttemptTimer(key, active);
      }
      bufferedAcks.splice(0).forEach(handlePortAck);
    };

    receive((command) => {
      if (!validateAttempt(command)) return;

      if (command.type === "PRESENTATION.CANCEL_TRANSACTION") {
        rememberWatermark(watermarkKey(command), {
          attempt: command.attempt,
          attemptId: command.attemptId,
        });
        cancelMatching((active) => (
          active.kind === "presentation"
          && active.correlation.transactionId === command.transactionId
        ));
        dispatchControl(command);
        return;
      }

      if (command.type === "MOTION.ABORT") {
        rememberWatermark(watermarkKey(command), {
          attempt: command.attempt,
          attemptId: command.attemptId,
        });
        cancelMatching((active) => (
          active.kind === "motion"
          && active.correlation.transactionId === command.transactionId
          && active.correlation.operationId === command.operationId
        ));
        dispatchControl(command);
        return;
      }

      const kind = attemptKind(command);
      if (kind) dispatchAttempt(command, kind);
    });

    return () => {
      if (cleaned) return;
      cleaned = true;
      disposed = true;
      try {
        subscriptionCleanup();
      } catch {
        // Continue deterministic cleanup even if a port has a faulty unsubscriber.
      }
      [...activeByOperation.entries()].forEach(([key, active]) => {
        clearAttempt(key, active, true);
      });
      bufferedAcks.length = 0;
      watermarks.clear();
    };
  });
}

export const sceneRuntimeGateway = createSceneRuntimeGateway();
