import {
  assign,
  enqueueActions,
  sendParent,
  setup,
  type SnapshotFrom,
} from "xstate";
import {
  bridgeCommand,
  dismissStepCommand,
  revealStepCommand,
  zoneRevealBeforeToken,
} from "../../statecharts/domain/commandBuilders";
import type {
  ZonePresentationFailureEvent,
  ZoneSessionContext,
  ZoneSessionEvent,
  ZoneSessionInput,
  ZoneSessionServices,
} from "./types";

const MAX_PRESENTATION_ATTEMPTS = 2;

function matchesSettled(expected: string | null, event: ZoneSessionEvent): boolean {
  return event.type === "PRESENTATION.SETTLED" && event.token === expected;
}

function matchesFailure(
  expected: string | null,
  transactionId: string | null,
  event: ZoneSessionEvent,
): event is ZonePresentationFailureEvent {
  return (event.type === "PRESENTATION.FAILED"
      || event.type === "PRESENTATION.TIMED_OUT")
    && expected !== null
    && event.token === expected
    && event.operationId === expected.replace(/:attempt:\d+$/u, "")
    && event.transactionId === transactionId;
}

function initialContext(input: ZoneSessionInput): ZoneSessionContext {
  return {
    initialStatus: input.initialStatus,
    revealPlan: null,
    revealBeforeActionIndex: 0,
    revealStepIndex: 0,
    revealCommandToken: null,
    revealCommandAttempt: 1,
    dismissPlan: null,
    dismissStepIndex: 0,
    dismissCommandToken: null,
    dismissCommandAttempt: 1,
    linkedNavigationPlanId: null,
    linkedNavigationTransactionId: null,
    linkedMotionToken: null,
  };
}

/**
 * Owns the complete special-zone reveal/dismiss transaction. It is the sole
 * issuer of zone presentation commands; the parent only routes events and
 * projects the child snapshot for backwards-compatible diagnostics.
 */
export function createZoneSessionMachine(services: ZoneSessionServices) {
  return setup({
    types: {} as {
      context: ZoneSessionContext;
      events: ZoneSessionEvent;
      input: ZoneSessionInput;
    },
    guards: {
      initiallyActive: ({ context }) => context.initialStatus === "active",
      hasRevealPlan: ({ context }) => context.revealPlan !== null,
      hasRevealBeforeAction: ({ context }) => (
        context.revealPlan !== null
        && context.revealBeforeActionIndex
          < context.revealPlan.beforeRevealBridgeActions.length
      ),
      hasRevealStep: ({ context }) => (
        context.revealPlan !== null
        && context.revealStepIndex < context.revealPlan.steps.length
      ),
      hasDismissPlan: ({ context }) => context.dismissPlan !== null,
      hasDismissStep: ({ context }) => (
        context.dismissPlan !== null
        && context.dismissStepIndex < context.dismissPlan.steps.length
      ),
      hasLinkedNavigation: ({ context }) => (
        context.linkedNavigationPlanId !== null
        && context.dismissPlan?.linkedNavigationPlanId
          === context.linkedNavigationPlanId
      ),
      hasStandaloneDismiss: ({ context }) => (
        context.dismissPlan !== null
        && context.dismissPlan.linkedNavigationPlanId === null
      ),
      revealSettledMatches: ({ context, event }) => (
        matchesSettled(context.revealCommandToken, event)
      ),
      revealCanRetry: ({ context, event }) => (
        matchesFailure(
          context.revealCommandToken,
          context.revealPlan?.id ?? null,
          event,
        ) && context.revealCommandAttempt < MAX_PRESENTATION_ATTEMPTS
      ),
      revealFailureMatches: ({ context, event }) => matchesFailure(
        context.revealCommandToken,
        context.revealPlan?.id ?? null,
        event,
      ),
      dismissSettledMatches: ({ context, event }) => (
        matchesSettled(context.dismissCommandToken, event)
      ),
      dismissCanRetry: ({ context, event }) => (
        matchesFailure(
          context.dismissCommandToken,
          context.linkedNavigationTransactionId
            ?? context.dismissPlan?.linkedNavigationPlanId
            ?? context.dismissPlan?.id
            ?? null,
          event,
        ) && context.dismissCommandAttempt < MAX_PRESENTATION_ATTEMPTS
      ),
      dismissFailureMatches: ({ context, event }) => matchesFailure(
        context.dismissCommandToken,
        context.linkedNavigationTransactionId
          ?? context.dismissPlan?.linkedNavigationPlanId
          ?? context.dismissPlan?.id
          ?? null,
        event,
      ),
      linkedDepartureMatches: ({ context, event }) => (
        event.type === "MOTION.DEPARTED"
        && context.dismissPlan !== null
        && context.linkedNavigationPlanId !== null
        && context.dismissPlan.linkedNavigationPlanId
          === context.linkedNavigationPlanId
        && event.token === context.linkedMotionToken
      ),
    },
    actions: {
      planReveal: assign(({ event }) => {
        if (event.type !== "ZONE.REVEAL.REQUESTED") return {};
        return {
          revealPlan: services.planReveal(event.nodeId),
          revealBeforeActionIndex: 0,
          revealStepIndex: 0,
          revealCommandToken: null,
          revealCommandAttempt: 1,
        };
      }),
      planDismiss: assign(({ event }) => {
        if (event.type !== "ZONE.DISMISS.REQUESTED") return {};
        return {
          dismissPlan: services.planDismiss(event.nodeId),
          dismissStepIndex: 0,
          dismissCommandToken: null,
          dismissCommandAttempt: 1,
          linkedNavigationPlanId: null,
          linkedNavigationTransactionId: null,
          linkedMotionToken: null,
        };
      }),
      armLinkedDismiss: assign(({ event }) => {
        if (event.type !== "ZONE.LINKED_DISMISS.ARMED") return {};
        return {
          dismissPlan: event.plan,
          dismissStepIndex: 0,
          dismissCommandToken: null,
          dismissCommandAttempt: 1,
          linkedNavigationPlanId: event.navigationPlanId,
          linkedNavigationTransactionId: event.navigationTransactionId,
          linkedMotionToken: event.motionToken,
        };
      }),
      issueRevealBefore: enqueueActions(({ context, enqueue }) => {
        const plan = context.revealPlan;
        const action = plan?.beforeRevealBridgeActions[
          context.revealBeforeActionIndex
        ];
        if (!plan || !action) return;
        const operationId = zoneRevealBeforeToken(
          plan.id,
          context.revealBeforeActionIndex,
        );
        const command = bridgeCommand(
          operationId,
          context.revealCommandAttempt,
          "zone-reveal-before",
          plan.id,
          context.revealBeforeActionIndex,
          action,
        );
        enqueue.assign({ revealCommandToken: command.token });
        enqueue(() => services.executePresentation(command));
      }),
      commitRevealBefore: assign(({ context }) => {
        const plan = context.revealPlan;
        if (!plan) return {};
        services.commitRevealBeforeAction(
          plan.id,
          context.revealBeforeActionIndex,
        );
        return {
          revealBeforeActionIndex: context.revealBeforeActionIndex + 1,
          revealCommandToken: null,
          revealCommandAttempt: 1,
        };
      }),
      issueRevealStep: enqueueActions(({ context, enqueue }) => {
        if (!context.revealPlan) return;
        const command = revealStepCommand(
          context.revealPlan,
          context.revealStepIndex,
          context.revealCommandAttempt,
        );
        enqueue.assign({ revealCommandToken: command.token });
        enqueue(() => services.executePresentation(command));
      }),
      commitRevealStep: assign(({ context }) => {
        if (!context.revealPlan) return {};
        services.commitRevealStep(
          context.revealPlan.id,
          context.revealStepIndex,
        );
        return {
          revealStepIndex: context.revealStepIndex + 1,
          revealCommandToken: null,
          revealCommandAttempt: 1,
        };
      }),
      finishReveal: assign({
        revealPlan: null,
        revealBeforeActionIndex: 0,
        revealStepIndex: 0,
        revealCommandToken: null,
        revealCommandAttempt: 1,
      }),
      notifyStandaloneRevealSettled: ({ context }) => {
        if (!context.revealPlan) return;
        services.onStandaloneTransactionSettled?.(Object.freeze({
          transactionId: context.revealPlan.id,
          kind: "reveal" as const,
        }));
      },
      issueDismissStep: enqueueActions(({ context, enqueue }) => {
        if (!context.dismissPlan) return;
        const command = dismissStepCommand(
          context.dismissPlan,
          context.dismissStepIndex,
          context.dismissCommandAttempt,
          context.linkedNavigationTransactionId,
        );
        enqueue.assign({ dismissCommandToken: command.token });
        enqueue(() => services.executePresentation(command));
      }),
      commitDismissStep: assign(({ context }) => {
        if (!context.dismissPlan) return {};
        services.commitDismissStep(
          context.dismissPlan.id,
          context.dismissStepIndex,
        );
        return {
          dismissStepIndex: context.dismissStepIndex + 1,
          dismissCommandToken: null,
          dismissCommandAttempt: 1,
        };
      }),
      finishDismiss: assign({
        dismissPlan: null,
        dismissStepIndex: 0,
        dismissCommandToken: null,
        dismissCommandAttempt: 1,
        linkedNavigationPlanId: null,
        linkedNavigationTransactionId: null,
        linkedMotionToken: null,
      }),
      notifyStandaloneDismissSettled: ({ context }) => {
        const plan = context.dismissPlan;
        if (!plan || plan.linkedNavigationPlanId !== null) return;
        services.onStandaloneTransactionSettled?.(Object.freeze({
          transactionId: plan.id,
          kind: "dismiss" as const,
        }));
      },
      retryReveal: enqueueActions(({ context, event, enqueue }) => {
        if (!matchesFailure(
          context.revealCommandToken,
          context.revealPlan?.id ?? null,
          event,
        )) return;
        const nextAttempt = context.revealCommandAttempt + 1;
        enqueue.assign({
          revealCommandAttempt: nextAttempt,
          revealCommandToken: null,
        });
        enqueue(() => services.onOperationRetry?.(Object.freeze({
          transactionId: event.transactionId,
          operationId: event.operationId,
          failedAttemptId: event.token,
          nextAttempt,
          reason: event.error,
        })));
      }),
      retryDismiss: enqueueActions(({ context, event, enqueue }) => {
        const transactionId = context.linkedNavigationTransactionId
          ?? context.dismissPlan?.linkedNavigationPlanId
          ?? context.dismissPlan?.id
          ?? null;
        if (!matchesFailure(context.dismissCommandToken, transactionId, event)) return;
        const nextAttempt = context.dismissCommandAttempt + 1;
        enqueue.assign({
          dismissCommandAttempt: nextAttempt,
          dismissCommandToken: null,
        });
        enqueue(() => services.onOperationRetry?.(Object.freeze({
          transactionId: event.transactionId,
          operationId: event.operationId,
          failedAttemptId: event.token,
          nextAttempt,
          reason: event.error,
        })));
      }),
      notifyFailure: sendParent(({ event }) => ({
        type: "ORCHESTRATION.ZONE.RECOVERY.REQUESTED" as const,
        failure: event as ZonePresentationFailureEvent,
      })),
      notifyCleanupComplete: sendParent(({ context }) => ({
        type: "ORCHESTRATION.CLEANUP.COMPLETE" as const,
        navigationPlanId: context.linkedNavigationPlanId as string,
      })),
    },
  }).createMachine({
    id: "zone-session",
    initial: "initializing",
    context: ({ input }) => initialContext(input),
    states: {
      initializing: {
        always: [
          { guard: "initiallyActive", target: "active" },
          { target: "inactive" },
        ],
      },
      inactive: {
        on: {
          "ZONE.REVEAL.REQUESTED": {
            target: "planningRevealFromInactive",
          },
          "ZONE.DISMISS.REQUESTED": {
            target: "planningDismissFromInactive",
          },
          "ZONE.LINKED_DISMISS.ARMED": {
            actions: "armLinkedDismiss",
          },
          "MOTION.DEPARTED": {
            guard: "linkedDepartureMatches",
            target: "selectingDismissStep",
          },
        },
      },
      planningRevealFromInactive: {
        entry: "planReveal",
        always: [
          { guard: "hasRevealPlan", target: "selectingRevealBeforeAction" },
          { target: "inactive" },
        ],
      },
      planningRevealFromActive: {
        entry: "planReveal",
        always: [
          { guard: "hasRevealPlan", target: "selectingRevealBeforeAction" },
          { target: "active" },
        ],
      },
      selectingRevealBeforeAction: {
        always: [
          { guard: "hasRevealBeforeAction", target: "revealBeforeBridge" },
          { target: "selectingRevealStep" },
        ],
      },
      revealBeforeBridge: {
        entry: "issueRevealBefore",
        on: {
          "PRESENTATION.SETTLED": {
            guard: "revealSettledMatches",
            target: "selectingRevealBeforeAction",
            actions: "commitRevealBefore",
          },
          "PRESENTATION.FAILED": [
            { guard: "revealCanRetry", target: "revealBeforeBridge", reenter: true, actions: "retryReveal" },
            { guard: "revealFailureMatches", target: "failed", actions: "notifyFailure" },
          ],
          "PRESENTATION.TIMED_OUT": [
            { guard: "revealCanRetry", target: "revealBeforeBridge", reenter: true, actions: "retryReveal" },
            { guard: "revealFailureMatches", target: "failed", actions: "notifyFailure" },
          ],
        },
      },
      selectingRevealStep: {
        always: [
          { guard: "hasRevealStep", target: "revealing" },
          {
            target: "active",
            actions: ["notifyStandaloneRevealSettled", "finishReveal"],
          },
        ],
      },
      revealing: {
        entry: "issueRevealStep",
        on: {
          "PRESENTATION.SETTLED": {
            guard: "revealSettledMatches",
            target: "selectingRevealStep",
            actions: "commitRevealStep",
          },
          "PRESENTATION.FAILED": [
            { guard: "revealCanRetry", target: "revealing", reenter: true, actions: "retryReveal" },
            { guard: "revealFailureMatches", target: "failed", actions: "notifyFailure" },
          ],
          "PRESENTATION.TIMED_OUT": [
            { guard: "revealCanRetry", target: "revealing", reenter: true, actions: "retryReveal" },
            { guard: "revealFailureMatches", target: "failed", actions: "notifyFailure" },
          ],
        },
      },
      active: {
        on: {
          "ZONE.REVEAL.REQUESTED": { target: "planningRevealFromActive" },
          "ZONE.DISMISS.REQUESTED": { target: "planningDismissFromActive" },
          "ZONE.LINKED_DISMISS.ARMED": { actions: "armLinkedDismiss" },
          "MOTION.DEPARTED": {
            guard: "linkedDepartureMatches",
            target: "selectingDismissStep",
          },
        },
      },
      planningDismissFromInactive: {
        entry: "planDismiss",
        always: [
          { guard: "hasDismissPlan", target: "selectingDismissStep" },
          { target: "inactive" },
        ],
      },
      planningDismissFromActive: {
        entry: "planDismiss",
        always: [
          { guard: "hasDismissPlan", target: "selectingDismissStep" },
          { target: "active" },
        ],
      },
      selectingDismissStep: {
        always: [
          { guard: "hasDismissStep", target: "dismissing" },
          {
            guard: "hasLinkedNavigation",
            target: "inactive",
            actions: ["notifyCleanupComplete", "finishDismiss"],
          },
          {
            guard: "hasStandaloneDismiss",
            target: "inactive",
            actions: ["notifyStandaloneDismissSettled", "finishDismiss"],
          },
          { target: "inactive", actions: "finishDismiss" },
        ],
      },
      dismissing: {
        entry: "issueDismissStep",
        on: {
          "PRESENTATION.SETTLED": {
            guard: "dismissSettledMatches",
            target: "selectingDismissStep",
            actions: "commitDismissStep",
          },
          "PRESENTATION.FAILED": [
            { guard: "dismissCanRetry", target: "dismissing", reenter: true, actions: "retryDismiss" },
            { guard: "dismissFailureMatches", target: "failed", actions: "notifyFailure" },
          ],
          "PRESENTATION.TIMED_OUT": [
            { guard: "dismissCanRetry", target: "dismissing", reenter: true, actions: "retryDismiss" },
            { guard: "dismissFailureMatches", target: "failed", actions: "notifyFailure" },
          ],
        },
      },
      failed: {},
    },
  });
}

export type ZoneSessionMachine = ReturnType<typeof createZoneSessionMachine>;
export type ZoneSessionSnapshot = SnapshotFrom<ZoneSessionMachine>;
