import type { CharacterSettleMachineSnapshot } from "./machine";
import type {
  CharacterForceSettleCommand,
  CharacterSettleMachineOutput,
} from "./types";

export function selectCharacterSettleCommand(
  snapshot: CharacterSettleMachineSnapshot,
): CharacterForceSettleCommand | null {
  return snapshot.matches("issuingForceSettle") ? snapshot.context.command : null;
}

export function selectCharacterSettleOutcome(
  snapshot: CharacterSettleMachineSnapshot,
): CharacterSettleMachineOutput | null {
  return snapshot.status === "done" ? snapshot.output : null;
}
