/**
 * Public character-phase projection. Navigation owns the real settle actor and
 * every character command; this region contains no lifecycle side effects.
 */
export const characterRegion = {
  initial: "idle",
  on: {
    "ORCHESTRATION.MOTION.ISSUED": { target: ".departing" },
    "MOTION.DEPARTED": {
      guard: "navigationMotionEventRelevant",
      target: ".running",
    },
    "MOTION.ARRIVED": {
      guard: "navigationMotionEventRelevant",
      target: ".settling",
    },
    "ORCHESTRATION.NAVIGATION.PHASE_CHANGED": [
      {
        guard: { type: "navigationPhaseMatches", params: { phase: "idle" } },
        target: ".idle",
      },
      {
        guard: {
          type: "navigationPhaseMatches",
          params: { phase: "awaiting-character-settle" },
        },
        target: ".settling",
      },
      {
        guard: {
          type: "navigationPhaseMatches",
          params: { phase: "awaiting-linked-cleanup" },
        },
        target: ".idle",
      },
    ],
  },
  states: {
    idle: { tags: ["character-idle"] },
    departing: { tags: ["character-moving"] },
    running: { tags: ["character-moving"] },
    settling: { tags: ["character-settling"] },
  },
} as const;
