import {
  assign,
  enqueueActions,
  sendParent,
  sendTo,
  setup,
  type SnapshotEvent,
  type SnapshotFrom,
} from "xstate";
import {
  createCharacterSettleMachine,
  selectCharacterSettleCommand,
  type CharacterSettleMachineOutput,
  type CharacterSettleMachineSnapshot,
} from "../character-settle";
import {
  correlationMatches,
  linkedCleanupCorrelation,
  navigationCharacterSettleCommand,
  navigationMotionCommand,
  navigationPresentationCommand,
  navigationSettleCorrelation,
  validateNavigationCorrelation,
} from "./protocol";
import type {
  NavigationContext,
  NavigationCorrelation,
  NavigationEvent,
  NavigationFailure,
  NavigationIntent,
  NavigationMachineInput,
  NavigationMachineServices,
  NavigationParentEvent,
  NavigationRejection,
  NavigationSettledNotice,
} from "./types";

const MAX_PRESENTATION_ATTEMPTS = 2;

function frozenIntent(event: Extract<NavigationEvent, { type: "NAVIGATION.REQUESTED" }>): NavigationIntent {
  return Object.freeze({
    epoch: event.epoch,
    sequence: event.sequence,
    transactionId: event.transactionId,
    operationId: event.operationId,
    attemptId: event.attemptId,
    attempt: event.attempt,
    targetNodeId: event.targetNodeId,
  });
}

function initialContext(input: NavigationMachineInput): NavigationContext {
  const lifecycle = validateNavigationCorrelation(input.correlation, {
    allowSequenceZero: true,
  });
  return {
    lifecycle: Object.freeze({ ...lifecycle }),
    currentNodeId: input.initialNodeId,
    latestSequence: lifecycle.sequence,
    activeIntent: null,
    queuedIntent: null,
    plan: null,
    linkedDismissPlan: null,
    stageIndex: 0,
    beforeActionIndex: 0,
    afterActionIndex: 0,
    presentationCommand: null,
    motionCommand: null,
    characterCommand: null,
    presentationAttempt: 1,
    stageStartedCommitted: false,
    arrivedNodeId: null,
    characterVisualIdle: input.initialCharacterVisualIdle ?? true,
    linkedCleanupComplete: true,
    linkedCleanupCorrelation: null,
    rejection: null,
    failure: null,
  };
}

function currentStage(context: NavigationContext) {
  return context.plan?.stages[context.stageIndex] ?? null;
}

function characterSnapshotFromEvent(
  event: unknown,
): CharacterSettleMachineSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<CharacterSettleMachineSnapshot>).snapshot;
}

function characterOutputFromEvent(
  event: unknown,
): CharacterSettleMachineOutput | null {
  if (typeof event !== "object" || event === null || !("output" in event)) return null;
  return (event as { readonly output?: CharacterSettleMachineOutput }).output ?? null;
}

function commandCorrelation(
  command: NavigationCorrelation | null,
): NavigationCorrelation | null {
  return command
    ? {
        epoch: command.epoch,
        sequence: command.sequence,
        transactionId: command.transactionId,
        operationId: command.operationId,
        attemptId: command.attemptId,
        attempt: command.attempt,
      }
    : null;
}

function settledNotice(context: NavigationContext): NavigationSettledNotice {
  if (!context.activeIntent || !context.plan) {
    throw new Error("Settled navigation is missing its active transaction.");
  }
  return Object.freeze({
    type: "NAVIGATION.SETTLED" as const,
    ...navigationSettleCorrelation(context.activeIntent),
    planId: context.plan.id,
    nodeId: context.currentNodeId,
  });
}

function tokenAndCorrelationMatch(
  expected: (NavigationCorrelation & { readonly token: string }) | null,
  event: NavigationCorrelation & { readonly token: string },
): boolean {
  return expected !== null
    && event.token === expected.token
    && correlationMatches(expected, event);
}

function failureKind(
  event: Extract<NavigationEvent, {
    type:
      | "PRESENTATION.FAILED"
      | "PRESENTATION.TIMED_OUT"
      | "MOTION.FAILED"
      | "MOTION.TIMED_OUT"
      | "CHARACTER.FAILED";
  }>,
): NavigationFailure["kind"] {
  switch (event.type) {
    case "PRESENTATION.FAILED": return "presentation-failed";
    case "PRESENTATION.TIMED_OUT": return "presentation-timeout";
    case "MOTION.FAILED": return "motion-failed";
    case "MOTION.TIMED_OUT": return "motion-timeout";
    case "CHARACTER.FAILED": return event.timedOut
      ? "character-timeout"
      : "character-failed";
  }
}

function failureFromEvent(
  context: NavigationContext,
  event: Extract<NavigationEvent, {
    type:
      | "PRESENTATION.FAILED"
      | "PRESENTATION.TIMED_OUT"
      | "MOTION.FAILED"
      | "MOTION.TIMED_OUT"
      | "CHARACTER.FAILED";
  }>,
): NavigationFailure {
  return Object.freeze({
    epoch: event.epoch,
    sequence: event.sequence,
    transactionId: event.transactionId,
    operationId: event.operationId,
    attemptId: event.attemptId,
    attempt: event.attempt,
    kind: failureKind(event),
    error: event.error,
    safeNodeId: context.currentNodeId,
    planId: context.plan?.id ?? null,
  });
}

function resetTransaction(
  context: NavigationContext,
  activeIntent: NavigationIntent | null,
): Partial<NavigationContext> {
  return {
    activeIntent,
    queuedIntent: null,
    plan: null,
    linkedDismissPlan: null,
    stageIndex: 0,
    beforeActionIndex: 0,
    afterActionIndex: 0,
    presentationCommand: null,
    motionCommand: null,
    characterCommand: null,
    presentationAttempt: 1,
    stageStartedCommitted: false,
    arrivedNodeId: null,
    linkedCleanupComplete: true,
    linkedCleanupCorrelation: null,
    rejection: null,
    failure: null,
    characterVisualIdle: context.characterVisualIdle,
  };
}

/**
 * Focused navigation workflow. It is the sole owner of navigation planning,
 * stage execution, retry, the linked-zone cleanup barrier and final character
 * settlement. It never targets an orchestrator state; terminal failures are
 * emitted as fully correlated parent events.
 */
export function createNavigationMachine(services: NavigationMachineServices) {
  return setup({
    types: {} as {
      context: NavigationContext;
      events: NavigationEvent;
      input: NavigationMachineInput;
    },
    actors: {
      characterSettleWorkflow: createCharacterSettleMachine({
        naturalSettleTimeoutMs: services.characterNaturalSettleTimeoutMs,
        forcedSettleAckTimeoutMs: services.characterForceSettleAckTimeoutMs,
      }),
    },
    guards: {
      newerIntent: ({ context, event }) => (
        event.type === "NAVIGATION.REQUESTED"
        && event.epoch === context.lifecycle.epoch
        && event.epoch.length > 0
        && event.transactionId.length > 0
        && event.operationId.length > 0
        && event.targetNodeId.length > 0
        && event.sequence > context.latestSequence
        && event.attempt === 1
        && event.attemptId === `${event.operationId}:attempt:1`
      ),
      hasPlan: ({ context }) => context.plan !== null,
      hasStages: ({ context }) => (context.plan?.stages.length ?? 0) > 0,
      hasBeforeAction: ({ context }) => {
        const stage = currentStage(context);
        return stage !== null
          && context.beforeActionIndex < stage.beforeTravelBridgeActions.length;
      },
      hasAfterAction: ({ context }) => {
        const stage = currentStage(context);
        return stage !== null
          && context.afterActionIndex < stage.afterArrivalBridgeActions.length;
      },
      hasMoreStages: ({ context }) => (
        context.plan !== null && context.stageIndex < context.plan.stages.length
      ),
      shouldArmLinkedCleanup: ({ context }) => (
        context.stageIndex === 0
        && context.linkedDismissPlan !== null
        && context.motionCommand !== null
      ),
      linkedCleanupArmedMatches: ({ context, event }) => (
        event.type === "ZONE.CLEANUP.ARMED"
        && event.navigationPlanId === context.plan?.id
        && tokenAndCorrelationMatch(context.motionCommand, event)
      ),
      presentationAckMatches: ({ context, event }) => (
        event.type === "PRESENTATION.SETTLED"
        && tokenAndCorrelationMatch(context.presentationCommand, event)
      ),
      presentationFailureMatches: ({ context, event }) => (
        (event.type === "PRESENTATION.FAILED"
          || event.type === "PRESENTATION.TIMED_OUT")
        && tokenAndCorrelationMatch(context.presentationCommand, event)
      ),
      presentationCanRetry: ({ context, event }) => (
        (event.type === "PRESENTATION.FAILED"
          || event.type === "PRESENTATION.TIMED_OUT")
        && tokenAndCorrelationMatch(context.presentationCommand, event)
        && context.presentationAttempt < MAX_PRESENTATION_ATTEMPTS
      ),
      motionAckMatches: ({ context, event }) => (
        (event.type === "MOTION.DEPARTED"
          || event.type === "MOTION.ARRIVED"
          || event.type === "MOTION.VISUAL_IDLE")
        && tokenAndCorrelationMatch(context.motionCommand, event)
      ),
      arrivalMatches: ({ context, event }) => (
        event.type === "MOTION.ARRIVED"
        && tokenAndCorrelationMatch(context.motionCommand, event)
        && event.nodeId === currentStage(context)?.toNodeId
      ),
      motionFailureMatches: ({ context, event }) => (
        (event.type === "MOTION.FAILED" || event.type === "MOTION.TIMED_OUT")
        && tokenAndCorrelationMatch(context.motionCommand, event)
      ),
      visualIdleMatches: ({ context, event }) => (
        event.type === "MOTION.VISUAL_IDLE"
        && tokenAndCorrelationMatch(context.motionCommand, event)
        && event.nodeId === context.arrivedNodeId
      ),
      characterAlreadyIdle: ({ context }) => context.characterVisualIdle,
      characterSettleSucceeded: ({ event }) => (
        characterOutputFromEvent(event)?.status === "settled"
      ),
      characterAckMatches: ({ context, event }) => (
        (event.type === "CHARACTER.SETTLED" || event.type === "CHARACTER.FAILED")
        && tokenAndCorrelationMatch(
          context.characterCommand
            ? { ...context.characterCommand, token: context.characterCommand.attemptId }
            : null,
          event,
        )
      ),
      cleanupMatches: ({ context, event }) => (
        event.type === "ZONE.CLEANUP.COMPLETED"
        && event.navigationPlanId === context.plan?.id
        && correlationMatches(context.linkedCleanupCorrelation, event)
      ),
      cleanupComplete: ({ context }) => context.linkedCleanupComplete,
      hasQueuedIntent: ({ context }) => context.queuedIntent !== null,
    },
    actions: {
      acceptIntent: assign(({ event }) => {
        if (event.type !== "NAVIGATION.REQUESTED") return {};
        validateNavigationCorrelation(event);
        return {
          activeIntent: frozenIntent(event),
          queuedIntent: null,
          latestSequence: event.sequence,
          rejection: null,
          failure: null,
        };
      }),
      queueLatestIntent: assign(({ event }) => {
        if (event.type !== "NAVIGATION.REQUESTED") return {};
        validateNavigationCorrelation(event);
        return {
          queuedIntent: frozenIntent(event),
          latestSequence: event.sequence,
        };
      }),
      planNavigation: assign(({ context }) => {
        const intent = context.activeIntent;
        if (!intent) return {};
        let result;
        try {
          result = services.planNavigation(context.currentNodeId, intent.targetNodeId);
        } catch (error) {
          const rejection: NavigationRejection = Object.freeze({
            type: "NAVIGATION.REJECTED",
            ...intent,
            sourceNodeId: context.currentNodeId,
            targetNodeId: intent.targetNodeId,
            reason: "rule-conflict",
            detail: error instanceof Error ? error.message : "navigation-planner-failed",
          });
          return { plan: null, rejection };
        }
        if (!result.accepted) {
          const rejection: NavigationRejection = Object.freeze({
            type: "NAVIGATION.REJECTED",
            ...intent,
            sourceNodeId: context.currentNodeId,
            targetNodeId: intent.targetNodeId,
            reason: result.reason,
            detail: result.detail,
          });
          return { plan: null, rejection };
        }
        const plan = result.plan;
        const invalid = plan.sourceNodeId !== context.currentNodeId
          || plan.targetNodeId !== intent.targetNodeId
          || plan.stages.some((stage, index) => stage.index !== index);
        if (invalid) {
          const rejection: NavigationRejection = Object.freeze({
            type: "NAVIGATION.REJECTED",
            ...intent,
            sourceNodeId: context.currentNodeId,
            targetNodeId: intent.targetNodeId,
            reason: "rule-conflict",
            detail: "navigation-plan-correlation-mismatch",
          });
          return { plan: null, rejection };
        }
        const cleanup = result.concurrentZoneDismissalPlan === null
          ? null
          : linkedCleanupCorrelation(intent);
        return {
          plan,
          linkedDismissPlan: result.concurrentZoneDismissalPlan,
          stageIndex: 0,
          beforeActionIndex: 0,
          afterActionIndex: 0,
          presentationCommand: null,
          motionCommand: null,
          characterCommand: null,
          presentationAttempt: 1,
          stageStartedCommitted: false,
          arrivedNodeId: null,
          linkedCleanupComplete: cleanup === null,
          linkedCleanupCorrelation: cleanup,
          rejection: null,
          failure: null,
        };
      }),
      issueBeforePresentation: enqueueActions(({ context, enqueue }) => {
        if (!context.activeIntent || !context.plan) return;
        const command = navigationPresentationCommand(
          context.activeIntent,
          context.plan,
          context.stageIndex,
          "before",
          context.beforeActionIndex,
          context.presentationAttempt,
        );
        enqueue.assign({ presentationCommand: command });
        enqueue(() => services.executePresentation(command));
      }),
      commitBeforePresentation: assign(({ context }) => {
        if (!context.plan) return {};
        services.commitNavigationBeforeAction(
          context.plan.id,
          context.stageIndex,
          context.beforeActionIndex,
        );
        return {
          beforeActionIndex: context.beforeActionIndex + 1,
          presentationCommand: null,
          presentationAttempt: 1,
        };
      }),
      prepareMotion: enqueueActions(({ context, enqueue }) => {
        if (!context.activeIntent || !context.plan) return;
        const command = navigationMotionCommand(
          context.activeIntent,
          context.plan,
          context.stageIndex,
        );
        enqueue.assign({
          motionCommand: command,
          characterCommand: null,
          stageStartedCommitted: false,
          arrivedNodeId: null,
          characterVisualIdle: false,
        });
      }),
      executePreparedMotion: ({ context }) => {
        if (!context.motionCommand) {
          throw new Error("Navigation motion must be prepared before it is executed.");
        }
        services.executeMotion(context.motionCommand);
      },
      notifyLinkedCleanup: sendParent(({ context }) => {
        const intent = context.activeIntent;
        const plan = context.plan;
        const dismiss = context.linkedDismissPlan;
        const motion = context.motionCommand;
        const completion = context.linkedCleanupCorrelation;
        if (!intent || !plan || !dismiss || !motion || !completion) {
          throw new Error("Linked cleanup notification requires a complete navigation transaction.");
        }
        return {
          type: "NAVIGATION.LINKED_ZONE_CLEANUP.REQUESTED",
          ...commandCorrelation(motion) as NavigationCorrelation,
          plan: dismiss,
          navigationPlanId: plan.id,
          motionToken: motion.token,
          completion,
        } satisfies NavigationParentEvent;
      }),
      commitStageStarted: assign(({ context }) => {
        if (!context.plan || context.stageStartedCommitted) return {};
        services.commitNavigationStageStarted(context.plan.id, context.stageIndex);
        return { stageStartedCommitted: true };
      }),
      recordArrival: assign(({ event }) => {
        if (event.type !== "MOTION.ARRIVED") return {};
        return {
          currentNodeId: event.nodeId,
          arrivedNodeId: event.nodeId,
          afterActionIndex: 0,
          presentationCommand: null,
          presentationAttempt: 1,
          characterVisualIdle: false,
        };
      }),
      markVisualIdle: assign({ characterVisualIdle: true }),
      issueAfterPresentation: enqueueActions(({ context, enqueue }) => {
        if (!context.activeIntent || !context.plan) return;
        const command = navigationPresentationCommand(
          context.activeIntent,
          context.plan,
          context.stageIndex,
          "after",
          context.afterActionIndex,
          context.presentationAttempt,
        );
        enqueue.assign({ presentationCommand: command });
        enqueue(() => services.executePresentation(command));
      }),
      commitAfterPresentation: assign(({ context }) => {
        if (!context.plan || !context.arrivedNodeId) return {};
        services.commitNavigationAfterAction(
          context.plan.id,
          context.stageIndex,
          context.afterActionIndex,
          context.arrivedNodeId,
        );
        return {
          afterActionIndex: context.afterActionIndex + 1,
          presentationCommand: null,
          presentationAttempt: 1,
        };
      }),
      completeStage: assign(({ context }) => {
        if (!context.plan || !context.arrivedNodeId) return {};
        services.commitNavigationStageArrived(
          context.plan.id,
          context.stageIndex,
          context.arrivedNodeId,
        );
        return {
          stageIndex: context.stageIndex + 1,
          beforeActionIndex: 0,
          afterActionIndex: 0,
          presentationCommand: null,
          presentationAttempt: 1,
          stageStartedCommitted: false,
          characterCommand: null,
        };
      }),
      retryPresentation: enqueueActions(({ context, event, enqueue }) => {
        if (event.type !== "PRESENTATION.FAILED"
          && event.type !== "PRESENTATION.TIMED_OUT") return;
        const nextAttempt = context.presentationAttempt + 1;
        enqueue.assign({
          presentationAttempt: nextAttempt,
          presentationCommand: null,
        });
        enqueue(() => services.onOperationRetry?.(Object.freeze({
          epoch: event.epoch,
          sequence: event.sequence,
          transactionId: event.transactionId,
          operationId: event.operationId,
          attemptId: event.attemptId,
          attempt: event.attempt,
          failedAttemptId: event.attemptId,
          nextAttempt,
          reason: event.error,
        })));
      }),
      recordFailure: assign(({ context, event }) => {
        if (event.type !== "PRESENTATION.FAILED"
          && event.type !== "PRESENTATION.TIMED_OUT"
          && event.type !== "MOTION.FAILED"
          && event.type !== "MOTION.TIMED_OUT"
          && event.type !== "CHARACTER.FAILED") return {};
        return { failure: failureFromEvent(context, event) };
      }),
      markCleanupComplete: assign({ linkedCleanupComplete: true }),
      dispatchCharacterSettleCommand: enqueueActions(({ context, event, enqueue }) => {
        const snapshot = characterSnapshotFromEvent(event);
        const childCommand = snapshot ? selectCharacterSettleCommand(snapshot) : null;
        if (!childCommand || !context.activeIntent || !context.motionCommand
          || !context.arrivedNodeId) return;
        const command = navigationCharacterSettleCommand(
          context.activeIntent,
          context.motionCommand,
          context.arrivedNodeId,
          childCommand.operationId,
          childCommand.attemptId,
          childCommand.attempt,
        );
        enqueue.assign({ characterCommand: command });
        enqueue(() => services.executeCharacterForceSettle?.(command));
        enqueue.sendTo("characterSettleWorkflow", {
          type: "CHARACTER.SETTLE.COMMAND_DISPATCHED",
          attemptId: command.attemptId,
        });
      }),
      forwardVisualIdleToCharacter: sendTo(
        "characterSettleWorkflow",
        ({ event }) => {
          if (event.type !== "MOTION.VISUAL_IDLE") {
            throw new Error("Expected a correlated visual-idle event.");
          }
          return { type: event.type, token: event.token, nodeId: event.nodeId };
        },
      ),
      forwardCharacterAck: sendTo(
        "characterSettleWorkflow",
        ({ event }) => {
          if (event.type !== "CHARACTER.SETTLED" && event.type !== "CHARACTER.FAILED") {
            throw new Error("Expected a correlated character acknowledgement.");
          }
          return event.type === "CHARACTER.SETTLED"
            ? {
                type: event.type,
                transactionId: event.transactionId,
                operationId: event.operationId,
                attemptId: event.attemptId,
                attempt: event.attempt,
              }
            : {
                type: event.type,
                transactionId: event.transactionId,
                operationId: event.operationId,
                attemptId: event.attemptId,
                attempt: event.attempt,
                error: event.error,
                timedOut: event.timedOut,
              };
        },
      ),
      completeCharacterSettle: assign(({ event }) => {
        const output = characterOutputFromEvent(event);
        if (output?.status !== "settled") return {};
        return {
          currentNodeId: output.arrivedNodeId,
          arrivedNodeId: output.arrivedNodeId,
          characterVisualIdle: true,
        };
      }),
      recordCharacterSettleFailure: assign(({ context, event }) => {
        const output = characterOutputFromEvent(event);
        if (output?.status !== "failed" || !context.activeIntent) return {};
        return {
          failure: Object.freeze({
            epoch: context.activeIntent.epoch,
            sequence: context.activeIntent.sequence,
            transactionId: context.activeIntent.transactionId,
            operationId: output.failure.command.operationId,
            attemptId: output.failure.command.attemptId,
            attempt: output.failure.command.attempt,
            kind: output.failure.kind === "force-settle-timeout"
              ? "character-timeout" as const
              : "character-failed" as const,
            error: output.failure.error,
            safeNodeId: context.currentNodeId,
            planId: context.plan?.id ?? null,
          }),
        };
      }),
      recordCharacterActorFailure: assign(({ context, event }) => {
        const base = context.characterCommand ?? context.motionCommand;
        const intent = context.activeIntent;
        if (!base || !intent) return {};
        return {
          failure: Object.freeze({
            ...commandCorrelation(base) as NavigationCorrelation,
            kind: "child-actor-failed" as const,
            error: typeof event === "object" && event !== null && "error" in event
              ? `Character settle actor failed: ${String(event.error)}`
              : "Character settle actor failed without an error payload.",
            safeNodeId: context.currentNodeId,
            planId: context.plan?.id ?? null,
          }),
        };
      }),
      closeSettledTransaction: ({ context }) => {
        services.onTransactionSettled?.(settledNotice(context));
      },
      notifySettled: sendParent(({ context }) => (
        settledNotice(context) satisfies NavigationParentEvent
      )),
      notifyRejected: sendParent(({ context }) => {
        if (!context.rejection) {
          throw new Error("Rejected navigation is missing rejection details.");
        }
        return context.rejection satisfies NavigationParentEvent;
      }),
      notifyRecovery: sendParent(({ context }) => {
        if (!context.failure) {
          throw new Error("Failed navigation is missing failure details.");
        }
        return {
          type: "NAVIGATION.RECOVERY.REQUESTED",
          ...context.failure,
        } satisfies NavigationParentEvent;
      }),
      closeTransaction: assign(({ context }) => resetTransaction(context, null)),
      promoteQueuedIntent: assign(({ context }) => {
        if (!context.queuedIntent) return {};
        return resetTransaction(context, context.queuedIntent);
      }),
    },
  }).createMachine({
    id: "navigation-workflow",
    initial: "idle",
    context: ({ input }) => initialContext(input),
    on: {
      "NAVIGATION.REQUESTED": {
        guard: "newerIntent",
        actions: "queueLatestIntent",
      },
      "ZONE.CLEANUP.COMPLETED": {
        guard: "cleanupMatches",
        actions: "markCleanupComplete",
      },
      "MOTION.VISUAL_IDLE": {
        guard: "visualIdleMatches",
        actions: "markVisualIdle",
      },
    },
    states: {
      idle: {
        tags: ["navigation-idle"],
        on: {
          "NAVIGATION.REQUESTED": {
            guard: "newerIntent",
            target: "planning",
            actions: "acceptIntent",
          },
        },
      },
      planning: {
        tags: ["navigation-busy", "navigation-planning"],
        entry: "planNavigation",
        always: [
          { guard: "hasPlan", target: "selectingBeforeAction" },
          { target: "rejected" },
        ],
      },
      selectingBeforeAction: {
        tags: ["navigation-busy", "navigation-planning"],
        always: [
          { guard: "hasBeforeAction", target: "beforeBridge" },
          { guard: "hasStages", target: "issuingMotion" },
          { target: "selectingSettle" },
        ],
      },
      beforeBridge: {
        tags: ["navigation-busy", "navigation-before-bridge"],
        entry: "issueBeforePresentation",
        on: {
          "PRESENTATION.SETTLED": {
            guard: "presentationAckMatches",
            target: "selectingBeforeAction",
            actions: "commitBeforePresentation",
          },
          "PRESENTATION.FAILED": [
            {
              guard: "presentationCanRetry",
              target: "beforeBridge",
              reenter: true,
              actions: "retryPresentation",
            },
            {
              guard: "presentationFailureMatches",
              target: "failed",
              actions: "recordFailure",
            },
          ],
          "PRESENTATION.TIMED_OUT": [
            {
              guard: "presentationCanRetry",
              target: "beforeBridge",
              reenter: true,
              actions: "retryPresentation",
            },
            {
              guard: "presentationFailureMatches",
              target: "failed",
              actions: "recordFailure",
            },
          ],
        },
      },
      issuingMotion: {
        tags: ["navigation-busy", "navigation-moving"],
        entry: "prepareMotion",
        always: [
          { guard: "shouldArmLinkedCleanup", target: "armingLinkedCleanup" },
          { target: "dispatchingMotion" },
        ],
      },
      armingLinkedCleanup: {
        tags: ["navigation-busy", "navigation-moving"],
        entry: "notifyLinkedCleanup",
        on: {
          "ZONE.CLEANUP.ARMED": {
            guard: "linkedCleanupArmedMatches",
            target: "dispatchingMotion",
          },
        },
      },
      dispatchingMotion: {
        tags: ["navigation-busy", "navigation-moving"],
        entry: "executePreparedMotion",
        always: "moving",
      },
      moving: {
        tags: ["navigation-busy", "navigation-moving"],
        on: {
          "MOTION.DEPARTED": {
            guard: "motionAckMatches",
            actions: "commitStageStarted",
          },
          "MOTION.ARRIVED": {
            guard: "arrivalMatches",
            target: "selectingAfterAction",
            actions: ["commitStageStarted", "recordArrival"],
          },
          "MOTION.FAILED": {
            guard: "motionFailureMatches",
            target: "failed",
            actions: "recordFailure",
          },
          "MOTION.TIMED_OUT": {
            guard: "motionFailureMatches",
            target: "failed",
            actions: "recordFailure",
          },
        },
      },
      selectingAfterAction: {
        tags: ["navigation-busy", "navigation-after-arrival"],
        always: [
          { guard: "hasAfterAction", target: "afterArrivalBridge" },
          { target: "completingStage" },
        ],
      },
      afterArrivalBridge: {
        tags: ["navigation-busy", "navigation-after-arrival"],
        entry: "issueAfterPresentation",
        on: {
          "PRESENTATION.SETTLED": {
            guard: "presentationAckMatches",
            target: "selectingAfterAction",
            actions: "commitAfterPresentation",
          },
          "PRESENTATION.FAILED": [
            {
              guard: "presentationCanRetry",
              target: "afterArrivalBridge",
              reenter: true,
              actions: "retryPresentation",
            },
            {
              guard: "presentationFailureMatches",
              target: "failed",
              actions: "recordFailure",
            },
          ],
          "PRESENTATION.TIMED_OUT": [
            {
              guard: "presentationCanRetry",
              target: "afterArrivalBridge",
              reenter: true,
              actions: "retryPresentation",
            },
            {
              guard: "presentationFailureMatches",
              target: "failed",
              actions: "recordFailure",
            },
          ],
        },
      },
      completingStage: {
        tags: ["navigation-busy", "navigation-after-arrival"],
        entry: "completeStage",
        always: [
          { guard: "hasMoreStages", target: "selectingBeforeAction" },
          { target: "selectingSettle" },
        ],
      },
      selectingSettle: {
        tags: ["navigation-busy", "navigation-awaiting-settle"],
        always: [
          { guard: "characterAlreadyIdle", target: "settleBarrier" },
          { target: "awaitingCharacterSettle" },
        ],
      },
      awaitingCharacterSettle: {
        tags: ["navigation-busy", "navigation-awaiting-settle"],
        invoke: {
          id: "characterSettleWorkflow",
          src: "characterSettleWorkflow",
          input: ({ context }) => {
            if (!context.motionCommand || !context.arrivedNodeId || !context.activeIntent) {
              throw new Error("Character settle requires a correlated final motion arrival.");
            }
            return {
              motionToken: context.motionCommand.token,
              transactionId: context.activeIntent.transactionId,
              motionOperationId: context.motionCommand.operationId,
              motionAttempt: context.motionCommand.attempt,
              arrivedNodeId: context.arrivedNodeId,
            };
          },
          onSnapshot: { actions: "dispatchCharacterSettleCommand" },
          onDone: [
            {
              guard: "characterSettleSucceeded",
              target: "settleBarrier",
              actions: "completeCharacterSettle",
            },
            {
              target: "failed",
              actions: "recordCharacterSettleFailure",
            },
          ],
          onError: {
            target: "failed",
            actions: "recordCharacterActorFailure",
          },
        },
        on: {
          "MOTION.VISUAL_IDLE": {
            guard: "visualIdleMatches",
            actions: ["markVisualIdle", "forwardVisualIdleToCharacter"],
          },
          "CHARACTER.SETTLED": {
            guard: "characterAckMatches",
            actions: "forwardCharacterAck",
          },
          "CHARACTER.FAILED": {
            guard: "characterAckMatches",
            actions: "forwardCharacterAck",
          },
        },
      },
      settleBarrier: {
        tags: ["navigation-busy", "navigation-awaiting-settle"],
        always: {
          guard: "cleanupComplete",
          target: "completed",
        },
        on: {
          "ZONE.CLEANUP.COMPLETED": {
            guard: "cleanupMatches",
            target: "completed",
            actions: "markCleanupComplete",
          },
        },
      },
      completed: {
        tags: ["navigation-busy"],
        entry: ["closeSettledTransaction", "notifySettled"],
        always: [
          { guard: "hasQueuedIntent", target: "planning", actions: "promoteQueuedIntent" },
          { target: "idle", actions: "closeTransaction" },
        ],
      },
      rejected: {
        entry: "notifyRejected",
        always: [
          { guard: "hasQueuedIntent", target: "planning", actions: "promoteQueuedIntent" },
          { target: "idle", actions: "closeTransaction" },
        ],
      },
      failed: {
        tags: ["navigation-failed"],
        entry: "notifyRecovery",
      },
    },
  });
}

export type NavigationMachineLogic = ReturnType<typeof createNavigationMachine>;
export type NavigationMachineSnapshot = SnapshotFrom<NavigationMachineLogic>;
