import type {
  ZoneSessionProjection,
  ZoneSessionStateValue,
} from "./types";
import type { ZoneSessionSnapshot } from "./machine";

const TRANSITIONAL = new Set<ZoneSessionStateValue>([
  "planningRevealFromInactive",
  "planningRevealFromActive",
  "selectingRevealBeforeAction",
  "revealBeforeBridge",
  "selectingRevealStep",
  "revealing",
  "planningDismissFromInactive",
  "planningDismissFromActive",
  "selectingDismissStep",
  "dismissing",
  "failed",
]);

export function projectZoneSession(
  snapshot: ZoneSessionSnapshot,
): ZoneSessionProjection {
  const phase = snapshot.value as ZoneSessionStateValue;
  return Object.freeze({
    phase,
    transitionActive: TRANSITIONAL.has(phase),
    revealPlan: snapshot.context.revealPlan,
    revealBeforeActionIndex: snapshot.context.revealBeforeActionIndex,
    revealStepIndex: snapshot.context.revealStepIndex,
    revealCommandToken: snapshot.context.revealCommandToken,
    revealCommandAttempt: snapshot.context.revealCommandAttempt,
    dismissPlan: snapshot.context.dismissPlan,
    dismissStepIndex: snapshot.context.dismissStepIndex,
    dismissCommandToken: snapshot.context.dismissCommandToken,
    dismissCommandAttempt: snapshot.context.dismissCommandAttempt,
  });
}
