/**
 * Geometry policy shared by every bridge in the dynamic bridge catalogue.
 *
 * The catalogue stores geometry only. Which bridge is currently visible is a
 * runtime rule decision and must not leak back into this module.
 */
export interface OverpassBridgeSpec {
  readonly curveStyle: "symmetric-eased-arch";
  readonly width: number;
  readonly deckThickness: number;
  readonly platformEdgeOffset: number;
  readonly straightApproachLength: number;
  readonly bridgeSurfaceY: number;
  readonly maximumSurfacePitchDegrees: number;
  readonly routingCost: number;
  readonly requiredClearance: number;
  /** Span required by the unmodified, full-height presentation profile. */
  readonly minimumChordLength: number;
}

export interface AdaptiveOverpassProfile {
  readonly bridge: Readonly<OverpassBridgeSpec>;
  readonly chordLength: number;
  readonly curveHalfRun: number;
  readonly predictedMaximumSurfacePitchDegrees: number;
  readonly approachWasShortened: boolean;
  readonly crownWasLowered: boolean;
}

export const OVERPASS_BRIDGE_SURFACE_Y = 1.9;
export const OVERPASS_PLATFORM_EDGE_OFFSET = 0.615;
export const OVERPASS_STRAIGHT_APPROACH_LENGTH = 0.9;
export const OVERPASS_MINIMUM_STRAIGHT_APPROACH_LENGTH = 0.22;
export const OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES = 48;
export const OVERPASS_DESIGN_SURFACE_PITCH_DEGREES = 47;
export const OVERPASS_MINIMUM_CROWN_ABOVE_PLATFORM = 0.08;
/**
 * Long spans complete their climb inside this physical distance on each side,
 * then meet across a level crown. Keeping the shoulder physical (rather than
 * normalized to the chord) preserves clearance over intermediate platforms.
 */
export const OVERPASS_ARCH_SHOULDER_RUN = 2.3;

const NODE_PATH_SURFACE_Y = 0.523;
const STRAIGHT_PATH_SURFACE_Y = 0.026;
const GEOMETRY_EPSILON = 0.000_001;
const ARCH_MAX_NORMALIZED_SLOPE = 1 / (
  0.08 / 2 + (0.65 - 0.08) + (1 - 0.65) / 2
);

const DEFAULT_BRIDGE_FIELDS = Object.freeze({
  curveStyle: "symmetric-eased-arch" as const,
  width: 0.64,
  deckThickness: 0.18,
  platformEdgeOffset: OVERPASS_PLATFORM_EDGE_OFFSET,
  maximumSurfacePitchDegrees: OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES,
  routingCost: 0.25,
  // Underpass auditing is deliberately disabled for this version. The value
  // remains positive because it is part of the reusable edge schema.
  requiredClearance: 3.23,
});

/** Full-size profile used whenever the chord has enough room. */
export const OVERPASS_BRIDGE_SPEC: Readonly<OverpassBridgeSpec> = Object.freeze({
  ...DEFAULT_BRIDGE_FIELDS,
  straightApproachLength: OVERPASS_STRAIGHT_APPROACH_LENGTH,
  bridgeSurfaceY: OVERPASS_BRIDGE_SURFACE_Y,
  minimumChordLength: calculateMinimumChordLength(
    OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES,
  ),
});

/**
 * Fits the same symmetric bridge language onto a shorter chord.
 *
 * Adaptation is deterministic and happens in two stages:
 * 1. shorten both flat approaches equally while preserving the full crown;
 * 2. once the approaches reach their safe minimum, lower the crown.
 *
 * The minimum approach keeps the node-to-road step transition complete before
 * the arch begins. The 47° design slope leaves one degree of numerical margin
 * below the public 48° contract.
 */
export function createAdaptiveOverpassProfile(
  chordLength: number,
  endpointSurfaceY = NODE_PATH_SURFACE_Y,
): AdaptiveOverpassProfile {
  assertPositiveFinite(chordLength, "Bridge chord length");
  assertPositiveFinite(endpointSurfaceY, "Bridge endpoint surface height");

  const availableHalfRunAndApproach = (
    chordLength / 2 - OVERPASS_PLATFORM_EDGE_OFFSET
  );
  const targetRise = OVERPASS_BRIDGE_SURFACE_Y - STRAIGHT_PATH_SURFACE_Y;
  const designPitchRadians = degreesToRadians(
    OVERPASS_DESIGN_SURFACE_PITCH_DEGREES,
  );
  const requiredHalfRunForFullCrown = targetRise
    * ARCH_MAX_NORMALIZED_SLOPE
    / Math.tan(designPitchRadians);
  const approachRoomAtFullCrown = (
    availableHalfRunAndApproach - requiredHalfRunForFullCrown
  );

  const straightApproachLength = approachRoomAtFullCrown
    >= OVERPASS_MINIMUM_STRAIGHT_APPROACH_LENGTH
    ? Math.min(
      OVERPASS_STRAIGHT_APPROACH_LENGTH,
      approachRoomAtFullCrown,
    )
    : OVERPASS_MINIMUM_STRAIGHT_APPROACH_LENGTH;
  const curveHalfRun = (
    availableHalfRunAndApproach - straightApproachLength
  );
  if (curveHalfRun <= GEOMETRY_EPSILON) {
    throw new Error(
      `Bridge chord ${chordLength.toFixed(4)}m is too short for its platform rims and approaches.`,
    );
  }

  const maximumRiseAtDesignPitch = curveHalfRun
    * Math.tan(designPitchRadians)
    / ARCH_MAX_NORMALIZED_SLOPE;
  const minimumBridgeSurfaceY = (
    endpointSurfaceY + OVERPASS_MINIMUM_CROWN_ABOVE_PLATFORM
  );
  const minimumRise = minimumBridgeSurfaceY - STRAIGHT_PATH_SURFACE_Y;
  if (maximumRiseAtDesignPitch + GEOMETRY_EPSILON < minimumRise) {
    throw new Error(
      `Bridge chord ${chordLength.toFixed(4)}m cannot rise above its ${endpointSurfaceY.toFixed(4)}m endpoint surface without exceeding ${OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES}°.`,
    );
  }

  const bridgeSurfaceY = Math.min(
    OVERPASS_BRIDGE_SURFACE_Y,
    STRAIGHT_PATH_SURFACE_Y + maximumRiseAtDesignPitch,
  );
  const actualRise = bridgeSurfaceY - STRAIGHT_PATH_SURFACE_Y;
  const effectiveRiseRun = Math.min(
    curveHalfRun,
    OVERPASS_ARCH_SHOULDER_RUN,
  );
  const predictedMaximumSurfacePitchDegrees = radiansToDegrees(Math.atan(
    actualRise * ARCH_MAX_NORMALIZED_SLOPE / effectiveRiseRun,
  ));
  if (
    predictedMaximumSurfacePitchDegrees
    > OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES + GEOMETRY_EPSILON
  ) {
    throw new Error(
      `Adaptive bridge pitch ${predictedMaximumSurfacePitchDegrees.toFixed(4)}° exceeds the ${OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES}° contract.`,
    );
  }

  return Object.freeze({
    bridge: Object.freeze({
      ...DEFAULT_BRIDGE_FIELDS,
      straightApproachLength,
      bridgeSurfaceY,
      minimumChordLength: calculateMinimumChordLengthForProfile(
        bridgeSurfaceY,
        straightApproachLength,
        OVERPASS_MAXIMUM_SURFACE_PITCH_DEGREES,
      ),
    }),
    chordLength,
    curveHalfRun,
    predictedMaximumSurfacePitchDegrees,
    approachWasShortened: (
      straightApproachLength
      < OVERPASS_STRAIGHT_APPROACH_LENGTH - GEOMETRY_EPSILON
    ),
    crownWasLowered: (
      bridgeSurfaceY < OVERPASS_BRIDGE_SURFACE_Y - GEOMETRY_EPSILON
    ),
  });
}

export function calculateMinimumChordLength(
  maximumPitchDegrees: number,
): number {
  return calculateMinimumChordLengthForProfile(
    OVERPASS_BRIDGE_SURFACE_Y,
    OVERPASS_STRAIGHT_APPROACH_LENGTH,
    maximumPitchDegrees,
  );
}

export function calculateMinimumChordLengthForProfile(
  bridgeSurfaceY: number,
  straightApproachLength: number,
  maximumPitchDegrees: number,
): number {
  assertPositiveFinite(bridgeSurfaceY, "Bridge crown height");
  assertPositiveFinite(straightApproachLength, "Bridge approach length");
  assertPitch(maximumPitchDegrees);
  const archRise = bridgeSurfaceY - STRAIGHT_PATH_SURFACE_Y;
  if (archRise <= 0) {
    throw new Error("Bridge crown must be above the straight-road surface.");
  }
  const halfRun = archRise * ARCH_MAX_NORMALIZED_SLOPE
    / Math.tan(degreesToRadians(maximumPitchDegrees));
  return 2 * (
    OVERPASS_PLATFORM_EDGE_OFFSET
    + straightApproachLength
    + halfRun
  );
}

function assertPositiveFinite(value: number, label: string): void {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${label} must be positive and finite.`);
  }
}

function assertPitch(value: number): void {
  if (!Number.isFinite(value) || value <= 0 || value >= 90) {
    throw new Error("Bridge pitch must be finite and between 0° and 90°.");
  }
}

function degreesToRadians(value: number): number {
  return value * Math.PI / 180;
}

function radiansToDegrees(value: number): number {
  return value * 180 / Math.PI;
}
