import type {
  NavigationMachineSnapshot,
} from "./machine";
import type {
  NavigationPhase,
  NavigationProjection,
} from "./types";

export function selectNavigationPhase(
  snapshot: NavigationMachineSnapshot,
): NavigationPhase {
  if (snapshot.matches("idle")) return "idle";
  if (snapshot.matches("beforeBridge")) return "before-bridge";
  if (snapshot.matches("issuingMotion")
    || snapshot.matches("armingLinkedCleanup")
    || snapshot.matches("moving")) return "moving";
  if (snapshot.matches("selectingAfterAction")
    || snapshot.matches("afterArrivalBridge")
    || snapshot.matches("completingStage")) return "after-arrival-bridge";
  if (snapshot.matches("awaitingCharacterSettle")
    || snapshot.matches("selectingSettle")) return "awaiting-character-settle";
  if (snapshot.matches("settleBarrier")) return "awaiting-linked-cleanup";
  if (snapshot.matches("failed")) return "failed";
  return "planning";
}

export function projectNavigation(
  snapshot: NavigationMachineSnapshot,
): NavigationProjection {
  const context = snapshot.context;
  return Object.freeze({
    phase: selectNavigationPhase(snapshot),
    epoch: context.lifecycle.epoch,
    latestSequence: context.latestSequence,
    currentNodeId: context.currentNodeId,
    activeTargetNodeId: context.activeIntent?.targetNodeId ?? null,
    queuedTargetNodeId: context.queuedIntent?.targetNodeId ?? null,
    planId: context.plan?.id ?? null,
    stageIndex: context.stageIndex,
    beforeActionIndex: context.beforeActionIndex,
    afterActionIndex: context.afterActionIndex,
    command: context.presentationCommand
      ?? context.characterCommand
      ?? context.motionCommand,
    characterVisualIdle: context.characterVisualIdle,
    linkedCleanupComplete: context.linkedCleanupComplete,
    failure: context.failure,
  });
}

export function selectNavigationIsBusy(
  snapshot: NavigationMachineSnapshot,
): boolean {
  return snapshot.hasTag("navigation-busy");
}

export function selectNavigationCanAcceptIntent(
  snapshot: NavigationMachineSnapshot,
): boolean {
  return !snapshot.matches("failed");
}
