import type { SnapshotFrom } from "xstate";
import type { OrchestrationServices } from "../domain/orchestrationTypes";
import { createInitialLearningPathContext } from "./context";
import { createLearningPathOrchestrationSetup } from "./setup";
import { characterRegion } from "./regions/character";
import { navigationRegion } from "./regions/navigation";
import { zoneSessionRegion } from "./regions/zoneSession";

/**
 * Creates the application orchestration machine. The injected services are a
 * closure dependency, so machine snapshots remain serializable and contain no
 * renderer, simulation, mesh, mixer, or animation objects.
 */
export function createLearningPathMachine(services: OrchestrationServices) {
  return createLearningPathOrchestrationSetup(services).createMachine({
    id: "learning-path-orchestration",
    initial: "live",
    context: ({ input }) => createInitialLearningPathContext(input),
    states: {
      live: {
        type: "parallel",
        on: {
          "ORCHESTRATION.CLEANUP.COMPLETE": {
            actions: "forwardLinkedCleanupComplete",
          },
          "ORCHESTRATION.CHARACTER.VISUAL_IDLE_CHANGED": {
            guard: "characterReadinessCanSync",
            actions: "syncCharacterVisualIdle",
          },
          "NAVIGATION.RECOVERY.REQUESTED": {
            target: "#learning-path-orchestration.recovering",
            actions: "recordNavigationRecoveryRequest",
          },
          "ORCHESTRATION.CHARACTER.FAILED": {
            target: "#learning-path-orchestration.degraded",
            actions: "recordCharacterFailure",
          },
          "ORCHESTRATION.ZONE.RECOVERY.REQUESTED": {
            target: "#learning-path-orchestration.recovering",
            actions: "recordZoneRecoveryRequest",
          },
        },
        states: {
          navigation: navigationRegion,

          zoneSession: zoneSessionRegion,

          character: characterRegion,
        },
      },
      recovering: {
        id: "recovering",
        tags: ["orchestration-recovering"],
        entry: "notifyRecoveryStarted",
        exit: "cleanupRecoveryAdapter",
        invoke: {
          id: "recoveryWorkflow",
          src: "recoveryWorkflow",
          input: ({ context }) => {
            if (!context.recoveryRequest) {
              throw new Error("Recovery state requires a recovery request.");
            }
            return services.prepareRecoveryInput(context.recoveryRequest);
          },
          onSnapshot: {
            actions: "dispatchRecoveryCommand",
          },
          onDone: {
            actions: "finalizeRecoveryWorkflow",
          },
          onError: {
            target: "degraded",
            actions: "recordRecoveryActorFailure",
          },
        },
        on: {
          "RECOVERY.COMMAND.SUCCEEDED": {
            actions: "forwardRecoveryAck",
          },
          "RECOVERY.COMMAND.FAILED": {
            actions: "forwardRecoveryAck",
          },
          "NAVIGATION.REQUESTED": {
            actions: "queueLatestNavigationIntent",
          },
          "ORCHESTRATION.RECOVERY.COMPLETE": {
            guard: "recoveryCompleteMatches",
            target: "live",
            actions: "completeRecovery",
          },
          "ORCHESTRATION.RECOVERY.FAILED": {
            guard: "recoveryFailedMatches",
            target: "degraded",
            actions: "recordRecoveryFailure",
          },
        },
      },
      degraded: {
        id: "degraded",
        tags: ["orchestration-degraded"],
      },
    },
  });
}

export type LearningPathMachineLogic = ReturnType<typeof createLearningPathMachine>;
export type LearningPathMachineSnapshot = SnapshotFrom<LearningPathMachineLogic>;

export {
  getLearningPathDebugSnapshot,
  isLearningPathBusy,
  isLearningPathNavigationIdle,
  isLearningPathZoneActive,
  isLearningPathZoneInactive,
  isLearningPathZoneTransitional,
} from "./selectors";

export type {
  LearningPathDebugSnapshot,
  LearningPathEvent,
  LearningPathMachineContext,
  LearningPathMachineInput,
  OrchestrationServices,
} from "../domain/orchestrationTypes";
