import type { SnapshotFrom } from "xstate";
import { commandForStep, type RecoveryMachineLogic } from "./machine";
import type { RecoveryCommand, RecoveryOutcome, RecoveryStep } from "./types";

export type RecoveryMachineSnapshot = SnapshotFrom<RecoveryMachineLogic>;

function stepForSnapshot(snapshot: RecoveryMachineSnapshot): RecoveryStep | null {
  if (snapshot.matches("cancellingPresentation")) return "cancelling-presentation";
  if (snapshot.matches("abortingMotion")) return "aborting-motion";
  if (snapshot.matches("compensating")) return "compensating";
  if (snapshot.matches("restoringRuleLedger")) return "restoring-rule-ledger";
  if (snapshot.matches("awaitingCharacterIdle")) return "awaiting-character-idle";
  return null;
}

/** The adapter dispatches this command once for each observed snapshot. */
export function selectRecoveryCommand(
  snapshot: RecoveryMachineSnapshot,
): RecoveryCommand | null {
  const step = stepForSnapshot(snapshot);
  return step ? commandForStep(snapshot.context, step) : null;
}

export function selectRecoveryOutcome(
  snapshot: RecoveryMachineSnapshot,
): RecoveryOutcome {
  const { context } = snapshot;
  if (snapshot.matches("succeeded")) {
    return Object.freeze({
      status: "succeeded",
      recoveryId: context.recoveryId,
      safeNodeId: context.safeNodeId,
      compensatedOperationCount: context.compensatedOperationCount,
    });
  }
  if (snapshot.matches("failed")) {
    if (!context.failure) {
      throw new Error("A failed recovery snapshot must contain failure details.");
    }
    return Object.freeze({
      status: "degraded",
      recoveryId: context.recoveryId,
      safeNodeId: context.safeNodeId,
      failure: context.failure,
    });
  }
  if (snapshot.matches("closed")) {
    return Object.freeze({ status: "closed", recoveryId: context.recoveryId });
  }
  return Object.freeze({ status: "running", recoveryId: context.recoveryId });
}
